            ('    private val thumbFailCount = java.util.concurrent.ConcurrentHashMap<String, Int>()', '    private val thumbFailCount = java.util.concurrent.ConcurrentHashMap<String, Int>()\n\n    /**\n     * 第 68 轮：**「这个地址上没有图片」**的失败原因标记。\n     *\n     * 实机复现：图床域名变成停放页后，某些路径回 **HTTP 200 + 0 字节**（Content-Type: text/html），\n     * 老实现把它记成「正文太小(0B)」并按**图床故障**做整域退避 —— 一个坏链接连坐同域其它封面。\n     * 现在这类失败单列：**只影响这一张**，不退避、不熔断。\n     */\n    private const val NOT_IMAGE = "不是图片正文"'),
            # 68b. 第 68 轮实机 bug：图床停放页回「200 + 0 字节」判成「正文太小(0B)」
            ('                    val bytes = resp.body.bytes()\n                    if (bytes.size < 64) null to "正文太小(${bytes.size}B)" else bytes to ""', '                    val bytes = resp.body.bytes()\n                    val ctype = resp.header("Content-Type").orEmpty().lowercase()\n                    // 第 68 轮**实机测出的 bug**：截图出现「图载失败：picmeta2025.sbs: 正文太小(0B)」。\n                    // 复现：GET https://picmeta2025.sbs/1.JPG -> **HTTP 200 + 0 字节 + Content-Type: text/html**\n                    // （该域名已成「停放页」：多数子路径回 403，某些路径回 200 空正文）。\n                    // 也就是说：**200 不代表拿到了图**；「正文为空」既不等于图床挂了，\n                    // 也不该按图床故障熔断整个域（那会连坐同域其它正常的图）。\n                    if (bytes.isEmpty()) null to NOT_IMAGE\n                    if (bytes.size < 64) null to "正文太小(${bytes.size}B)"\n                    // 防盗链页/错误页常也是 200 + HTML：按正文头判真伪，不把 HTML 交给解码器。\n                    val isHtml = ctype.contains("text/html") ||\n                        (bytes.size >= 2 && bytes[0] == \'<\'.code.toByte() && bytes[1] == \'!\'.code.toByte())\n                    if (isHtml) null to NOT_IMAGE else bytes to ""'),
