            ('        for (withRef in order) {\n            val (bytes, err) = thumbAttempt(url, host, withRef)\n            if (bytes != null) {\n                thumbRefererFirst[host] = withRef\n                lastThumbError = ""\n                // 第 64 轮：**成功就清零该域的失败计数**，避免历史失败让下一次偶发失败直接进长退避。\n                thumbFailCount.remove(host)\n                thumbDeadUntil.remove(host)\n                return bytes to ""\n            }\n            why = err\n        }', '        var notImage = false\n        for (withRef in order) {\n            val (bytes, err) = thumbAttempt(url, host, withRef)\n            if (bytes != null) {\n                thumbRefererFirst[host] = withRef\n                lastThumbError = ""\n                // 第 64 轮：**成功就清零该域的失败计数**，避免历史失败让下一次偶发失败直接进长退避。\n                thumbFailCount.remove(host)\n                thumbDeadUntil.remove(host)\n                return bytes to ""\n            }\n            why = err\n            // 第 68 轮：这类失败**不是图床的错**（这张图在那边本来就不是图片）。\n            // 不为它做整域退避，否则一个坏链接会让该图床所有封面跟着等。\n            if (err == NOT_IMAGE) notImage = true\n        }\n        if (notImage) {\n            lastThumbError = "$host 上没有这张图（返回非图片正文）"\n            return null to lastThumbError\n        }'),
