            ('        val fails = (thumbFailCount[host] ?: 0) + 1\n        thumbFailCount[host] = fails\n        val backoff = (1000L shl (fails - 1).coerceAtMost(3)).coerceAtMost(8_000L)\n        thumbDeadUntil[host] = System.currentTimeMillis() + backoff\n        lastThumbError = "$host: $why"\n        return null to lastThumbError', '        val fails = (thumbFailCount[host] ?: 0) + 1\n        thumbFailCount[host] = fails\n        // ★ 第 86 轮真机实测（用户报「头像有的加载不出来」）：\n        // 无代理环境下 pbs.twimg.com / i.imgur.com 这类**境外图床整体不可达**\n        // （curl 直连 code=000、7.7 秒超时；同机 baidu 0.2 秒 200）。\n        // 这类失败**不是"偶发风控"，而是"这个网络下一直不通"** ——\n        // 指数退避封顶 8 秒意味着每 8 秒界面就再白等一次 4~8 秒，\n        // 用户看到的就是"一直在转、有的干脆出不来"。\n        //\n        // 所以按原因区分：**连接层失败**（异常/超时/无法解析）直接封 5 分钟；\n        // 其它（HTTP 状态码等，可能是瞬时风控）仍走原来的指数退避。\n        val unreachable = why.contains("请求异常") || why.contains("timeout", true) ||\n            why.contains("Failed to connect", true) || why.contains("Unable to resolve", true)\n        val backoff = if (unreachable) THUMB_DEAD_UNREACHABLE_MS\n            else (1000L shl (fails - 1).coerceAtMost(3)).coerceAtMost(8_000L)\n        thumbDeadUntil[host] = System.currentTimeMillis() + backoff\n        lastThumbError = if (unreachable) "$host 在这个网络下连不上（已暂停重试）" else "$host: $why"\n        return null to lastThumbError'),
