            ('    /** [fetchThumbBytesSync] 的挂起外壳：并发闸门在这里生效（同步入口留给宿具与冷路径直接用）。 */\n    suspend fun fetchThumbBytes(url: String): Pair<ByteArray?, String> =', '    /**\n     * **经公共图片代理取图**（第 90 轮，修「有些订阅作者图载失败」）。\n     *\n     * 真机实测：部分头像在**境外图床**（i.imgur.com / pbs.twimg.com），\n     * 无代理环境下这些域整体不可达（curl code=000）；而 wsrv.nl 在本网络可达\n     * （200/2.6s）且能成功代理境外图片（实测 GitHub 头像 283KB、image/png）。\n     *\n     * 只作**兜底**：直连判定为「连不上」时才调用，正常图不会绕这一圈。\n     * 失败返回 null（调用方如实报错，不假装成功）。\n     */\n    suspend fun fetchThumbBytesViaProxy(url: String): ByteArray? = withContext(Dispatchers.IO) {\n        runCatching {\n            // wsrv.nl 要求 url 参数**不带 scheme**（实测：带 https:// 会 404）。\n            val bare = url.removePrefix("https://").removePrefix("http://")\n            val encoded = java.net.URLEncoder.encode(bare, "UTF-8")\n            val req = okhttp3.Request.Builder()\n                .url("https://wsrv.nl/?url=$encoded")\n                .header("User-Agent", UA)\n                .build()\n            thumbHttp.newCall(req).execute().use { resp ->\n                if (!resp.isSuccessful) return@use null\n                val b = resp.body?.bytes() ?: return@use null\n                // 与直连同一判据：太小的不是图（代理的错误 JSON 只有几十字节）。\n                if (b.size < 64) null else b\n            }\n        }.getOrNull()\n    }\n\n    /** [fetchThumbBytesSync] 的挂起外壳：并发闸门在这里生效（同步入口留给宿具与冷路径直接用）。 */\n    suspend fun fetchThumbBytes(url: String): Pair<ByteArray?, String> ='),
            # 91d. 官方 tagRe 增加查询形态
            ('    private val tagRe = Regex("""href="https://hanime1\\.me/tag/[^"]*"[^>]*>\\s*([^<]+?)\\s*<""")', '    // ★★ 第 91 轮修（用户报「官方站没有落实可点击搜索的标签」）：\n    // 原来只认 href="https://hanime1.me/tag/…" 这一种形态。\n    // 实测站点还有**查询参数形态**：href="…/search?tags%5B%5D=JK"（tags[]=JK），\n    // 只认前者会让一部分片子的标签整个取不到（详情页标签区因此是空的）。\n    // 现在两种都认（路径形态优先，查询形态兜底）。\n    private val tagRe = Regex("""href="https://hanime1\\.me/tag/[^"]*"[^>]*>\\s*([^<]+?)\\s*<""")\n    private val tagQueryRe = Regex("""tags(?:%5B%5D|\\[\\])?=([^&"]+)""")'),
