            ('                if (edgeHostsEnabled && isOfficialHost(hostname)) {\n                    val picked = edgeCandidates()\n                    val list = if (picked.isEmpty()) builtInNodes else picked\n                    val ips = list.mapNotNull { addrFor(hostname, it) }\n                    if (ips.isNotEmpty()) {\n                        lastDoh = "$hostname => 内置Hosts ${ips.joinToString(",") { it.hostAddress }}"\n                        return ips\n                    }\n                }', '                if (edgeHostsEnabled && isOfficialHost(hostname)) {\n                    val picked = edgeCandidates()\n                    // ★★ 第 91 轮修（用户报「官方站介绍页和首页很快，但视频加载变慢了」）：\n                    //\n                    // 原来 edgeCandidates() 只返回**一个**「最快节点」，DNS 就把它当唯一 IP\n                    // 交给所有官方域 —— 包括**视频 CDN 域**。\n                    // 单个 Cloudflare 边缘 IP 跑小页面够快，但大流量视频挤同一个 IP 会慢；\n                    // 且钉死单 IP 后 OkHttp 没有备选，一个 IP 抖动就整段卡住。\n                    //\n                    // 修法：**页面域仍用选中的节点（保持秒开），视频/媒体域返回全部候选**，\n                    // 让 OkHttp 自己轮询可用 IP。这样提速了播放，又不影响页面加载。\n                    val isMedia = mediaHostHint(hostname)\n                    val list = when {\n                        !isMedia && picked.isNotEmpty() -> picked\n                        else -> builtInNodes\n                    }\n                    val ips = list.mapNotNull { addrFor(hostname, it) }\n                    if (ips.isNotEmpty()) {\n                        lastDoh = "$hostname => 内置Hosts(${if (isMedia) "媒体-多节点" else "页面-单节点"}) " +\n                            ips.joinToString(",") { it.hostAddress }\n                        return ips\n                    }\n                }'),
            # 93b. ★★ profile() 抓取失败重试 2 次（修「统计时而有时而没有」）
            ('    fun profile(): HanimeProfile? {\n        val uid = userId() ?: return null\n        val html = runCatching { get("$BASE/user/$uid") }.getOrDefault("")\n        if (html.isBlank()) return null', '    fun profile(): HanimeProfile? {\n        val uid = userId() ?: return null\n        // ★ 第 93 轮修（用户报「id / 订阅者数 / 影片数时而显示时而不显示」）：\n        // 原来只抓**一次**，失败就返回 null（界面整块消失）。\n        // 现在失败重试 2 次、间隔递增 —— 这类"偶发失败"重试一次通常就成功。\n        var html = ""\n        for (attempt in 0 until 3) {\n            html = runCatching { get("$BASE/user/$uid") }.getOrDefault("")\n            if (html.isNotBlank()) break\n            if (attempt < 2) runCatching { Thread.sleep(600L * (attempt + 1)) }\n        }\n        if (html.isBlank()) return null'),
