            # 97a. ★★ 新增 HanimeArtist 模型（照 Han1meViewer 的 HanimeVideo.Artist）
            ('/** hanime1.me 详情页。 */\ndata class HanimeDetail(\n    val video: HanimeVideo,\n    val description: String,\n    val tags: List<String>,\n    val sources: List<Pair<Int, String>>, // 清晰度 -> 直链（带 secure 参数，有时效）\n    val related: List<HanimeVideo>,\n    val isFav: Boolean = false,\n    val isSaved: Boolean = false,\n    val saveListId: String = "",\n)', '/**\n * 详情页的作者（第 97 轮，照 Han1meViewer 的 HanimeVideo.Artist 复刻）。\n *\n * 参考实现从详情页取三样：\n *  · `#video-artist-name` 的文本 → 作者名；\n *  · 它**下一个兄弟元素**的文本 → 类型（如「里番」）；\n *  · 圆形头像 `img`（border-radius:50%）的 src → 头像；\n *  · `#video-subscribe-form` 里三个 input → 关注状态：\n *    subscribe-user-id / subscribe-artist-id / subscribe-status（"1" = 已关注）。\n *\n * 关注状态三件套缺失（未登录 / 镜像站）时 post 为 null —— 界面据此不摆关注按钮，\n * 而不是摆一个点了没反应的。\n */\ndata class HanimeArtist(\n    val name: String,\n    val avatarUrl: String,\n    /** 类型（参考实现叫 genre，如「里番」）。 */\n    val genre: String,\n    /** 关注所需的三个 id；为空 = 当前上下文拿不到关注能力（未登录/镜像站）。 */\n    val userId: String = "",\n    val artistId: String = "",\n    val isSubscribed: Boolean = false,\n) {\n    /** 能否关注（三个 id 齐全）。 */\n    val canSubscribe: Boolean get() = userId.isNotBlank() && artistId.isNotBlank()\n}\n\n/** hanime1.me 详情页。 */\ndata class HanimeDetail(\n    val video: HanimeVideo,\n    val description: String,\n    val tags: List<String>,\n    val sources: List<Pair<Int, String>>, // 清晰度 -> 直链（带 secure 参数，有时效）\n    val related: List<HanimeVideo>,\n    val isFav: Boolean = false,\n    val isSaved: Boolean = false,\n    val saveListId: String = "",\n    /** 第 97 轮：作者（头像/名称/类型/关注状态）。null = 这一页没解析到。 */\n    val artist: HanimeArtist? = null,\n)'),
