            # 97c. ★★ parseArtist：选择器照参考实现 Parser
            ('    // ---------- 登录 ----------', '    /**\n     * 解析详情页的作者块（第 97 轮，选择器照 Han1meViewer 的 Parser）。\n     *\n     * 取三样：作者名 / 类型 / 圆形头像，以及关注三件套（user-id、artist-id、status）。\n     * 关注三件套缺失（未登录或镜像站）时 `canSubscribe = false`，界面据此不摆按钮。\n     */\n    internal fun parseArtist(html: String): HanimeArtist? {\n        // 作者名：id="video-artist-name" 的文本\n        val name = Regex("""id="video-artist-name"[^>]*>\\s*([^<]{1,80}?)\\s*<""")\n            .find(html)?.groupValues?.get(1)?.let { unescape(it).trim() }.orEmpty()\n        if (name.isBlank()) return null\n        // 类型：作者名元素之后的下一个文本（参考实现取 nextElementSibling）\n        val genre = Regex("""id="video-artist-name"[\\s\\S]{0,400}?</[a-zA-Z]+>\\s*<[a-zA-Z]+[^>]*>\\s*([^<]{1,40}?)\\s*<""")\n            .find(html)?.groupValues?.get(1)?.let { unescape(it).trim() }.orEmpty()\n        // 圆形头像：参考实现用 border-radius:50% 的 img（属性顺序不定，两种写法都试）\n        val avatar = Regex("""<img[^>]*border-radius:\\s*50%[^>]*src="([^"]+)"""")\n            .find(html)?.groupValues?.get(1)\n            ?: Regex("""<img[^>]*src="([^"]+)"[^>]*border-radius:\\s*50%""")\n                .find(html)?.groupValues?.get(1)\n            ?: Regex("""id="video-user-avatar"[^>]*src="([^"]+)"""")\n                .find(html)?.groupValues?.get(1)\n            ?: ""\n        // 关注三件套：从 #video-subscribe-form 区块里找（限定在区块内，避免匹配到别处的同名 input）\n        val formAt = html.indexOf("video-subscribe-form")\n        val formBlock = if (formAt >= 0) html.substring(formAt, minOf(formAt + 2000, html.length)) else ""\n        fun field(nm: String) = Regex("""name=""" + nm + """"[^>]*value="([^"]*)"""")\n            .find(formBlock)?.groupValues?.get(1).orEmpty()\n        val uid = field("subscribe-user-id")\n        val aid = field("subscribe-artist-id")\n        val st = field("subscribe-status")\n        return HanimeArtist(\n            name = name,\n            avatarUrl = avatar,\n            genre = genre,\n            userId = uid,\n            artistId = aid,\n            isSubscribed = st == "1",\n        )\n    }\n\n    // ---------- 登录 ----------'),
            # 97f. ★★ subscribeArtist：关注/取关作者（照参考实现 POST /subscribe）
            ('    fun toggleFavorite(videoId: String, currentlyFaved: Boolean): Boolean {', '    /**\n     * **关注 / 取关作者**（第 97 轮，照 Han1meViewer 的 NetworkRepo.subscribeArtist）。\n     *\n     * 参考实现发 `POST /subscribe`，字段：\n     *   subscribe-user-id / subscribe-artist-id / subscribe-status（"1"=关注，"0"=取关）\n     * 并带 csrf-token。三个 id 来自详情页 #video-subscribe-form 的 input（见 parseArtist）。\n     *\n     * 返回**操作后的关注状态**（用站点回包判断，判不出来就按意图返回），\n     * 界面据此更新按钮；失败抛异常，由调用方如实提示（不假装成功）。\n     */\n    fun subscribeArtist(userId: String, artistId: String, subscribe: Boolean): Boolean {\n        require(userId.isNotBlank() && artistId.isNotBlank()) { "缺少关注所需的 id" }\n        val status = if (subscribe) "1" else "0"\n        val body = okhttp3.FormBody.Builder()\n            .add("subscribe-user-id", userId)\n            .add("subscribe-artist-id", artistId)\n            .add("subscribe-status", status)\n            .build()\n        val req = okhttp3.Request.Builder()\n            .url("$BASE/subscribe")\n            .header("Referer", "$BASE/")\n            .header("X-Requested-With", "XMLHttpRequest")\n            .post(body)\n            .build()\n        return http.newCall(req).execute().use { resp ->\n            val text = runCatching { resp.body?.string().orEmpty() }.getOrDefault("")\n            if (!resp.isSuccessful) throw IllegalStateException("HTTP ${resp.code}")\n            // 回包形态各版本不一：能判出状态就用它，判不出就按意图返回（不编造）。\n            val marked = Regex(""""subscribe-status"\\s*:\\s*"?([01])"""").find(text)\n                ?.groupValues?.get(1)\n            when (marked) {\n                "1" -> true\n                "0" -> false\n                else -> subscribe\n            }\n        }\n    }\n\n    fun toggleFavorite(videoId: String, currentlyFaved: Boolean): Boolean {'),
            # 97h. ★★ parseArtist 用站点给的 href 作搜索地址 + 正确取类型
            ('    internal fun parseArtist(html: String): HanimeArtist? {\n        // 作者名：id="video-artist-name" 的文本\n        val name = Regex("""id="video-artist-name"[^>]*>\\s*([^<]{1,80}?)\\s*<""")\n            .find(html)?.groupValues?.get(1)?.let { unescape(it).trim() }.orEmpty()\n        if (name.isBlank()) return null\n        // 类型：作者名元素之后的下一个文本（参考实现取 nextElementSibling）\n        val genre = Regex("""id="video-artist-name"[\\s\\S]{0,400}?</[a-zA-Z]+>\\s*<[a-zA-Z]+[^>]*>\\s*([^<]{1,40}?)\\s*<""")\n            .find(html)?.groupValues?.get(1)?.let { unescape(it).trim() }.orEmpty()', '    internal fun parseArtist(html: String): HanimeArtist? {\n        // ★ 第 97 轮：站点**自己在锚点上给了搜索链接**（实测镜像与官方同构）：\n        //     <a id="video-artist-name" href="…/search?query=作者名">作者名</a>\n        //   用它的 href 比我自己拼更可靠（站点改名/编码规则变了也跟得上），\n        //   拿不到 href 才退回按名字拼。\n        val anchor = Regex("""<a[^>]*id="video-artist-name"[^>]*>([\\s\\S]{0,200}?)</a>""")\n            .find(html)?.value.orEmpty()\n        val name = Regex("""id="video-artist-name"[^>]*>\\s*([^<]{1,80}?)\\s*<""")\n            .find(html)?.groupValues?.get(1)?.let { unescape(it).trim() }.orEmpty()\n        if (name.isBlank()) return null\n        // 作者作品搜索地址：优先用锚点 href（站点自己给的），否则按名字拼。\n        val searchUrl = Regex("""href="([^"]+)"""").find(anchor)?.groupValues?.get(1)\n            ?.replace("&amp;", "&").orEmpty()\n        // 类型：作者名锚点**之后的下一个 <a>**（参考实现取 nextElementSibling）。\n        // 实测结构：<a id=video-artist-name>名</a> <a …>2.5D</a>\n        val after = if (anchor.isNotEmpty()) {\n            val at = html.indexOf(anchor)\n            if (at >= 0) html.substring(at + anchor.length, minOf(at + anchor.length + 600, html.length)) else ""\n        } else ""\n        val genre = Regex("""<a[^>]*>\\s*([^<]{1,40}?)\\s*</a>""")\n            .find(after)?.groupValues?.get(1)?.let { unescape(it).trim() }.orEmpty()'),
