            ('        return HanimeDetail(\n            video.copy(title = title, thumb = thumb), desc, tags, sources, related,\n            isFav = isFav, isSaved = isSaved, saveListId = saveListId,\n            artist = artist,\n        )', '        val result = HanimeDetail(\n            video.copy(title = title, thumb = thumb), desc, tags, sources, related,\n            isFav = isFav, isSaved = isSaved, saveListId = saveListId,\n            artist = artist,\n        )\n        // 第 98 轮：写入缓存，下次点同一部片子直接命中（不再发请求）。\n        detailCache[video.url] = result to System.currentTimeMillis()\n        return result'),
            # 100a. ★★ subscribeArtist 补 _token + X-CSRF-TOKEN（原缺 ⇒ Laravel 419，关注不落实）
            ('    fun subscribeArtist(userId: String, artistId: String, subscribe: Boolean): Boolean {\n        require(userId.isNotBlank() && artistId.isNotBlank()) { "缺少关注所需的 id" }\n        val status = if (subscribe) "1" else "0"\n        val body = okhttp3.FormBody.Builder()\n            .add("subscribe-user-id", userId)\n            .add("subscribe-artist-id", artistId)\n            .add("subscribe-status", status)\n            .build()\n        val req = okhttp3.Request.Builder()\n            .url("$BASE/subscribe")\n            .header("Referer", "$BASE/")\n            .header("X-Requested-With", "XMLHttpRequest")\n            .post(body)\n            .build()', '    fun subscribeArtist(userId: String, artistId: String, subscribe: Boolean): Boolean {\n        require(userId.isNotBlank() && artistId.isNotBlank()) { "缺少关注所需的 id" }\n        val status = if (subscribe) "1" else "0"\n        // ★★ 第 100 轮修（用户报「关注按钮没落实」）：补上 Laravel 的 CSRF 令牌。\n        //\n        // 参考实现 HanimeSubscriptionService 的字段是（已逐条核对）：\n        //   @Field("_token") csrfToken        ← **表单里也要带**\n        //   @Field("subscribe-user-id"/"subscribe-artist-id"/"subscribe-status")\n        //   @Header("X-CSRF-TOKEN") csrfToken ← **请求头也要带**\n        // 上一版只带了三个 subscribe-* 字段，缺 _token 与 X-CSRF-TOKEN ——\n        // Laravel 会直接 419（Page Expired）把请求挡掉，关注自然「没落实」。\n        val token = csrfToken()\n        val body = okhttp3.FormBody.Builder()\n            .add("_token", token)\n            .add("subscribe-user-id", userId)\n            .add("subscribe-artist-id", artistId)\n            .add("subscribe-status", status)\n            .build()\n        val req = okhttp3.Request.Builder()\n            .url("$BASE/subscribe")\n            .header("Referer", "$BASE/")\n            .header("X-CSRF-TOKEN", token)\n            .header("X-Requested-With", "XMLHttpRequest")\n            .post(body)\n            .build()'),
            # 100b. ★★ 关注三件套健壮解析（原正则要求 name 在 value 前 + 双引号）
            ('        // 关注三件套：从 #video-subscribe-form 区块里找（限定在区块内，避免匹配到别处的同名 input）\n        val formAt = html.indexOf("video-subscribe-form")\n        val formBlock = if (formAt >= 0) html.substring(formAt, minOf(formAt + 2000, html.length)) else ""\n        fun field(nm: String) = Regex("""name=""" + nm + """"[^>]*value="([^"]*)"""")\n            .find(formBlock)?.groupValues?.get(1).orEmpty()\n        val uid = field("subscribe-user-id")\n        val aid = field("subscribe-artist-id")\n        val st = field("subscribe-status")', '        // ★★ 第 100 轮修（用户报「关注按钮没出现 / 关注没落实」）：\n        //\n        // 关注三件套原来用一条正则同时匹配 name 与 value —— 它要求 name 在 value 之前，\n        // 且只认双引号。真实页面里属性顺序与引号风格都可能不同，一旦不同就整条匹配不到，\n        // 于是 canSubscribe=false、按钮不出现（用户看到的就是「没有关注按钮」）。\n        //\n        // 现在改成**先切出整个 form 区块，再逐个 input 独立取 name 与 value**（顺序无关、引号无关）。\n        val formAt = html.indexOf("video-subscribe-form")\n        val formBlock = if (formAt >= 0) html.substring(formAt, minOf(formAt + 4000, html.length)) else ""\n        val inputRe = Regex("""<input[^>]*>""")\n        val nameRe = Regex("""name\\s*=\\s*["\']([^"\']*)["\']""")\n        val valueRe = Regex("""value\\s*=\\s*["\']([^"\']*)["\']""")\n        fun fieldIn(block: String, nm: String): String {\n            for (tag in inputRe.findAll(block)) {\n                val t = tag.value\n                val n = nameRe.find(t)?.groupValues?.get(1) ?: continue\n                if (n != nm) continue\n                return valueRe.find(t)?.groupValues?.get(1).orEmpty()\n            }\n            return ""\n        }\n        fun field(nm: String): String {\n            val v = fieldIn(formBlock, nm)\n            return if (v.isNotBlank()) v else fieldIn(html, nm)\n        }\n        val uid = field("subscribe-user-id")\n        val aid = field("subscribe-artist-id")\n        val st = field("subscribe-status")'),
