            ('    fun htmlOf(path: String): String {\n        val full = if (path.startsWith("http")) path else BASE + path\n        return get(full)\n    }', '    /**\n     * 站内页面 HTML 的**短缓存**（第 100 轮）。\n     *\n     * 为什么：`/subscriptions` 每次进「我的订阅」都重新抓一遍（用户会反复进出），\n     * 既慢又没必要。TTL 取 60 秒 —— 覆盖"来回切页面"的常见操作，\n     * 又足够短，关注/取消关注后最多 1 分钟就能看到更新。\n     *\n     * 另提供 [invalidateHtml] 供**关注成功后主动失效**，让「我的订阅」立刻能看到变化。\n     */\n    private val htmlCache = java.util.concurrent.ConcurrentHashMap<String, Pair<String, Long>>()\n    private const val HTML_TTL_MS = 60_000L\n\n    /** 主动失效某个站内页面的缓存（关注/取关成功后调用，让订阅页立即刷新）。 */\n    fun invalidateHtml(path: String) {\n        val full = if (path.startsWith("http")) path else BASE + path\n        htmlCache.remove(full)\n    }\n\n    /** 关注/取关后清掉**所有**站内页缓存：订阅列表与详情页都受影响，整清最省心也最不会漏。 */\n    fun invalidateAllHtml() { htmlCache.clear() }\n\n    fun htmlOf(path: String): String {\n        val full = if (path.startsWith("http")) path else BASE + path\n        htmlCache[full]?.let { (cached, ts) ->\n            if (System.currentTimeMillis() - ts < HTML_TTL_MS) return cached\n        }\n        val html = get(full)\n        htmlCache[full] = html to System.currentTimeMillis()\n        return html\n    }'),
