                '    /**\n     * 第 143 轮（真机报「移动流量下封面全挂、联通 WiFi 正常」）：**把封面 URL 规范到更通用的形态**。\n     *\n     * ① 非标准端口：5x5x/Lvmao 封面是 https://<cdn>:1443/p2/<hash>.jpg。\n     *    实测同一张图 443 / 1443 / 8443 三端口都可用（200 / 17008B），\n     *    但移动运营商对非标端口的策略与宽带不同 -> 统一走 443（标准端口）。\n     * ② 重复斜杠：中国x站列表页给 https://pic.892539.xyz//12/92543.jpg，\n     *    实测双斜杠超时、单斜杠 200 / 11835B -> 压成单个斜杠。\n     *\n     * 只改写成更通用的形态，不动 host 与路径语义；调用方保留原 URL 兜底，正常线路不受影响。\n     */\n    fun thumbNormalizeThumbUrl(raw: String): String {\n        return runCatching {\n            val u = java.net.URI(raw)\n            if (u.host.isNullOrBlank()) return raw\n            // 只改端口，不动路径。\n            // （曾试过把 // 压成 /，但实测两种形态都可能好也可能坏，取决于具体图片与时刻，\n            //   属图床不稳、不是斜杠问题，强行改写反而有害。）\n            if (u.port > 0 && u.port != 443 && u.port != 80) {\n                java.net.URI(u.scheme, u.userInfo, u.host, 443, u.path, u.query, u.fragment).toString()\n            } else raw\n        }.getOrDefault(raw)\n    }\n    /**\n     * 第 144 轮（用户报「移动流量下封面仍常取不到、稳定性差」）：**多端口候选**。\n     *\n     * 实测 5x5x/Lvmao 的封面图床 jhfduadgiyhas.com 在 443 / 1443 / 8443 三个端口都返回\n     * 同一张图（200 / 17008B / image/jpeg）。而移动运营商对非标准端口的策略与宽带不同，\n     * 且会随网络状况变化 —— 只押一个端口在移动网络下必然不稳。\n     *\n     * 按「最通用 -> 原样 -> 次通用」排序逐个尝试：\n     *   ① 443  ：标准端口，普适性最好；\n     *   ② 原样 ：站点自己给的地址（通常是 1443）；\n     *   ③ 8443 ：另一条实测可用的备用端口。\n     * 顺序有意让标准端口优先，这样本来正常的线路只是换了等价入口、不会变慢。\n     */\n    fun thumbUrlVariants(raw: String): List<String> {\n        val out = LinkedHashSet<String>()\n        runCatching {\n            val u = java.net.URI(raw)\n            if (u.host.isNullOrBlank()) return listOf(raw)\n            // 第 146 轮（实测数据）：**路径里重复斜杠要压成单个**。\n            // pic.892539.xyz//12/x.jpg -> 20.7s / 另一次 47s 超时；\n            // pic.892539.xyz/12/x.jpg  -> 5.3s / 16.9s。双斜杠让图床走了明显更慢的路径。\n            val p = u.path.orEmpty().replace(Regex("/{2,}"), "/")\n            fun at(port: Int) = java.net.URI(u.scheme, u.userInfo, u.host, port, p, u.query, u.fragment).toString()\n            out.add(at(443))\n            out.add(raw)\n            if (u.port != 8443) out.add(at(8443))\n        }.onFailure { out.add(raw) }\n        return out.toList()\n    }\n\n    fun fetchThumbBytesSync(rawUrl: String): Pair<ByteArray?, String> {\n        // 第 143 轮：规范化形态优先，原样兜底（两者相同则只试一次）。\n        val urls = thumbUrlVariants(rawUrl)\n        // host 与端口无关，直接用原 URL 取即可（变体只改端口）。\n        val host = runCatching { java.net.URI(rawUrl).host.orEmpty() }.getOrDefault("")\n        if (host.isBlank()) return null to "封面地址无主机"\n        if ((thumbDeadUntil[host] ?: 0L) > System.currentTimeMillis()) return null to "图床 $host 刚连不上，暂不发卡"\n        val order = if (thumbRefererFirst[host] == false) listOf(false, true) else listOf(true, false)\n        var why = "未取到"\n        var notImage = false\n        for (tryUrl in urls) {\n        for (withRef in order) {\n            val (bytes, err) = thumbAttempt(tryUrl, host, withRef)',
