            ('    private val xchinaDetailAt = java.util.concurrent.ConcurrentHashMap<String, Long>()\n', '    private val xchinaDetailAt = java.util.concurrent.ConcurrentHashMap<String, Long>()\n    // 第 59 轮：**所有板块共用**的详情缓存（原来只有 xchina 一条）。\n    private val boardPageCache = java.util.concurrent.ConcurrentHashMap<String, HanimeDetail>()\n    private val boardPageAt = java.util.concurrent.ConcurrentHashMap<String, Long>()\n    private const val BOARD_TTL_MS = 10 * 60_000L\n    private val boardPageGate = java.util.concurrent.ConcurrentHashMap<String, java.util.concurrent.CountDownLatch>()\n    @Volatile private var boardPageOwner: String = ""\n    private fun boardPageFresh(url: String): HanimeDetail? {\n        val t = boardPageAt[url] ?: return null\n        if (System.currentTimeMillis() - t > BOARD_TTL_MS) return null\n        return boardPageCache[url]\n    }\n    private fun boardPageRemember(url: String, d: HanimeDetail) {\n        boardPageCache[url] = d\n        boardPageAt[url] = System.currentTimeMillis()\n    }\n    fun clearBoardPageCache() {\n        boardPageCache.clear(); boardPageAt.clear()\n    }\n'),
            ('    fun boardPage(v: HanimeVideo): HanimeDetail? =\n        (if (isNativeBoardUrl(v.url)) runCatching { boardDetail(v) }.getOrNull() else null)\n            ?: runCatching { metaDetail(v) }.getOrNull()\n', '    fun boardPage(v: HanimeVideo): HanimeDetail? {\n        // 第 59 轮：命中的话直接返回；否则记录 in-flight，并发点击复用同一个请求。\n        boardPageFresh(v.url)?.let { return it }\n        val gate = boardPageGate.computeIfAbsent(v.url) { java.util.concurrent.CountDownLatch(1) }\n        if (gate.count > 0L && boardPageOwner != v.url) {\n            runCatching { gate.await(8, java.util.concurrent.TimeUnit.SECONDS) }\n            boardPageFresh(v.url)?.let { return it }\n        }\n        boardPageOwner = v.url\n        try {\n            val d = (if (isNativeBoardUrl(v.url)) runCatching { boardDetail(v) }.getOrNull() else null)\n                ?: runCatching { metaDetail(v) }.getOrNull()\n            if (d != null) boardPageRemember(v.url, d)\n            return d\n        } finally {\n            if (boardPageOwner == v.url) boardPageOwner = ""\n            boardPageGate.remove(v.url)?.countDown()\n        }\n    }\n'),
            ('    // ---------- 通用卡片解析（统一卡片 UI：非 MissAV 的站点都走这一套） ----------\n', '    /**\n     * 第 59 轮：**后台预取**（用户反馈「收藏页点进介绍页太慢」）。\n     *\n     * 收藏页一渲染就把可见项的详情先取回来；用户真点的时候命中缓存，直接秒开。\n     * 三条纪律：① 只写缓存，不返回给界面（界面仍走 boardPage，逻辑单一）；\n     *          ② 失败静默（别把预取的错报给用户，点进去时会如实再取一次）；\n     *          ③ 串行 + 小间隔（这些站有频控，预取不能变成压测）。\n     */\n    fun prefetchBoardPage(items: List<HanimeVideo>) {\n        if (items.isEmpty()) return\n        val todo = items.filter { boardPageFresh(it.url) == null }.take(PREFETCH_MAX)\n        if (todo.isEmpty()) return\n        Thread {\n            for (v in todo) {\n                if (boardPageFresh(v.url) != null) continue\n                runCatching { boardPage(v) }\n                runCatching { Thread.sleep(250) }   // 小间隔：别把站点打急\n            }\n        }.apply { isDaemon = true; priority = Thread.MIN_PRIORITY }.start()\n    }\n    /** 预取一次最多取几条（收藏页一屏大约这么多）。 */\n    private const val PREFETCH_MAX = 3\n'),
            ('    /** 板块列表：一次调用只发一发请求（各站都有频控，见 xchina 的 Cloudflare 记录）。 */\n    fun boardListing(siteName: String, base: String, tabPath: String?, page: Int): List<HanimeVideo> = when {\n        isXchinaSite(siteName) -> xchinaListing(base, tabPath ?: "/videos.html", page)\n        isQinavSite(siteName) -> qinavListing(base, tabPath ?: "/new.html", page)\n        siteName.equals(GANXIE_NAME, ignoreCase = true) -> gxListing(base, tabPath ?: "/vl/56.php", page)\n        siteName.equals(CO36_NAME, ignoreCase = true) -> co36Listing(base, tabPath, page)\n        siteName.equals("MissAV", ignoreCase = true) ->\n            missavListing(originOf(base), tabPath ?: "/cn/new", page)\n        else -> genericListing(siteName, base, page)\n    }\n', '    /**\n     * **板块列表缓存**（第 62 轮，用户要求「优化下板块加载速度」）。\n     *\n     * 为什么：boardListing 是板块页的**唯一入口**，但只有 xchina 一条自带缓存，\n     * 其余 5 个（qinav / 感谢 / co36 / MissAV / 通用）**每次进页都重新抓网页**。\n     * 用户在板块页来回切页签、翻页、返回再进，都在重复付这份网络开销。\n     *\n     * 键含 siteName|base|path|page 四段 —— **换站点 / 换线路 / 换页签 / 换页各算一条**：\n     * 这四件事本来就会改变内容，不能共用缓存。**换线路尤其重要**（不同线路内容可能不同）。\n     *\n     * 纪律：**只缓存非空结果** —— 空结果往往是失败或被频控，\n     * 缓存它会让用户反复看到空白（沿用 xchina 列表缓存那条既有纪律）。\n     */\n    private const val BOARD_LIST_TTL_MS = 3 * 60_000L\n    /** 第 63 轮：缓存条数上限（防长跑膨胀；超出先清过期、再清最早的一半）。 */\n    private const val BOARD_LIST_MAX = 256\n    private val boardListCache = java.util.concurrent.ConcurrentHashMap<String, List<HanimeVideo>>()\n    private val boardListAt = java.util.concurrent.ConcurrentHashMap<String, Long>()\n\n    /** 清掉板块列表缓存（用户显式刷新时调，避免看到旧数据）。 */\n    fun clearBoardListCache() {\n        boardListCache.clear()\n        boardListAt.clear()\n    }\n\n    /** 板块列表：一次调用只发一发请求（各站都有频控，见 xchina 的 Cloudflare 记录）。 */\n    fun boardListing(siteName: String, base: String, tabPath: String?, page: Int): List<HanimeVideo> {\n        // 第 62 轮：命中缓存直接返回。键含站点/线路/页签/页码，四者任一变化都不复用。\n        val key = siteName + "|" + base + "|" + (tabPath ?: "") + "|" + page\n        val at = boardListAt[key]\n        if (at != null && System.currentTimeMillis() - at <= BOARD_LIST_TTL_MS) {\n            boardListCache[key]?.let { hit ->\n                if (hit.isNotEmpty()) {\n                    // 第 63 轮修一个第 62 轮引入的**回归**：\n                    // genericListing 的翻页自校验依赖 firstPageCache[base] 作为基线；\n                    // 而命中缓存时 genericListing **根本不执行**，基线就不会被填 ——\n                    // 于是翻第 2 页时 pageDistinct(基线为空, 新页) 恒为 true，\n                    // 「换 ?page=N 再试」这条回退不触发，部分站点的『加载更多』会拿回重复页\n                    // （正是第 54 轮修过的那个问题）。\n                    // 这里把缓存值当基线补上：不额外发请求，又恢复自校验能力。\n                    if (page == 1) runCatching { firstPageCache[base] = hit }\n                    return hit\n                }\n            }\n        }\n        val out = when {\n            isXchinaSite(siteName) -> xchinaListing(base, tabPath ?: "/videos.html", page)\n            isQinavSite(siteName) -> qinavListing(base, tabPath ?: "/new.html", page)\n            siteName.equals(GANXIE_NAME, ignoreCase = true) -> gxListing(base, tabPath ?: "/vl/56.php", page)\n            siteName.equals(CO36_NAME, ignoreCase = true) -> co36Listing(base, tabPath, page)\n            siteName.equals("MissAV", ignoreCase = true) ->\n                missavListing(originOf(base), tabPath ?: "/cn/new", page)\n            else -> genericListing(siteName, base, page)\n        }\n        // 纪律：只缓存非空结果\n        if (out.isNotEmpty()) {\n            // 第 63 轮：**加容量上限 + 顺带清过期**（原来是无界 ConcurrentHashMap，长跑会持续膨胀）。\n            // 站点×页签×页数 的组合数量不大，256 条足够覆盖常用路径。\n            if (boardListCache.size >= BOARD_LIST_MAX) {\n                val now = System.currentTimeMillis()\n                // 先清过期的；还超就清掉最早写入的那一半（简单可靠的近似 LRU）。\n                boardListAt.entries.removeAll { now - it.value > BOARD_LIST_TTL_MS }\n                if (boardListCache.size >= BOARD_LIST_MAX) {\n                    boardListAt.entries.sortedBy { it.value }.take(boardListAt.size / 2)\n                        .forEach { e -> boardListAt.remove(e.key) }\n                    boardListCache.keys.retainAll(boardListAt.keys)\n                }\n            }\n            boardListCache[key] = out\n            boardListAt[key] = System.currentTimeMillis()\n        }\n        return out\n    }\n'),
            # 65. 第 65 轮实机 bug：co36 首页翻页拼出双斜杠 //page/2.html -> HTTP 404。
            ('    /** maccms 分类页的翻页是把 `/page/N` 插在 `.html` 之前——这个形式取自站内分页器自己写出的链接。 */\n    fun co36PagePath(path: String, page: Int): String =\n        if (page <= 1) path else path.removeSuffix(".html") + "/page/$page.html"', '    /** maccms 分类页的翻页是把 `/page/N` 插在 `.html` 之前——这个形式取自站内分页器自己写出的链接。 */\n    fun co36PagePath(path: String, page: Int): String {\n        if (page <= 1) return path\n        // 第 65 轮**实机测出的 bug**：首页 path 是 / ，\n        // 老写法拼出 //page/2.html（双斜杠）——实测该 URL 返回 HTTP 404，界面报「第 2 页加载失败」。\n        // 现在去掉结尾的斜杠再拼，保证只有一层。\n        val head = path.removeSuffix(".html").removeSuffix("/")\n        return head + "/page/$page.html"\n    }'),
            ('    fun co36MaxPage(path: String): Int = co36PagerMax[path.removeSuffix(".html")] ?: 0', '    fun co36MaxPage(path: String): Int {\n        // 第 65 轮**实机测出的 bug**：36co 的首页是固定聚合页 ——\n        // 实测首页 HTTP 200 但**一个分页链接都没有**，且 /page/2.html 返回 404。\n        // 老实现让它去翻第 2 页，界面于是报「第 2 页加载失败：HTTP 404」。\n        // 这里对首页直接宣告「只有 1 页」，界面据此不再显示/触发「加载更多」。\n        val p = path.removeSuffix(".html")\n        if (p.isBlank() || p == "/") return 1\n        return co36PagerMax[p] ?: 0\n    }'),
            # 69. 36co 站点定义：主线路改指可用域名（失效域名不放列表）
            ('        X99Site(\n            name = CO36_NAME,\n            desc = "麻豆网 36co · 18 家传媒分区（介绍页 + 网页播放 · 站内只有明文 80 可达，见下方实测说明）",\n            url = CO36_HOME,\n            lines = listOf(X99Line(CO36_HOME, "")),\n        ),', '        X99Site(\n            name = CO36_NAME,\n            desc = "麻豆网 36co · 18 家传媒分区（介绍页 + 网页播放 · 多备用域名，见线路菜单）",\n            url = CO36_HOME,\n            // 第 69 轮：**主域 36co.cc 已整站不可达**（用户 2026-10-06 提供两个备用域名）。\n            // 实测：www.25jm.cc 回 200（同一套站：同样 18 个栏目、同样 /index.php/vod/... 路径、\n            //       同样的封面主机 23.225.11.173:8443）；www.91gc.pro 也曾被 RST。\n            // 所以 25jm.cc 放在**第一位**（主线路），91gc.pro 留作备用。\n            //\n            // **注意：失效的 36co.cc 故意不放进列表**。列表里留着它会有两个害处：\n            //  ① 用户点了必然失败；② 更隐蔽的是 —— [selectedLine] 会优先返回**已保存的线路**，\n            //     旧版用户存过 http://www.36co.cc，只要它还在列表里就会被一直命中选择，\n            //     表现为「升级到新版仍然打不开」（本轮真机实测就是如此）。\n            //  移除它之后，保存的旧值匹配不到任何线路，自动回落到 lines.first()。\n            lines = listOf(\n                X99Line(CO36_HOME, ""),\n                X99Line("https://www.91gc.pro", ""),\n            ),\n        ),'),
            # 69b. CO36_HOME 改指可用域名 + 新增 co36Roots 根域集合
            ('    const val CO36_NAME = "36co"\n    const val CO36_HOME = "http://www.36co.cc"', '    const val CO36_NAME = "36co"\n\n    /**\n     * 36co 的首页（第 69 轮：**原 `http://www.36co.cc` 已整站不可达**）。\n     *\n     * 用户 2026-10-06 提供了两个备用域名，实测：\n     *  · `https://www.25jm.cc`  -> **HTTP 200**，同一套站（18 栏目 / 同样的 maccms 路径 /\n     *                            同样的封面主机 `23.225.11.173:8443`）；\n     *  · `https://www.91gc.pro` -> 与 36co.cc 一样被 RST（保留在备用线路里，日后可能恢复）。\n     * 因此主线路改指 25jm.cc。**根域集合见 [co36Roots]**（换域后仍要认得出这是同一个板块）。\n     */\n    // 第 139 轮（真机日志：Failed to connect to www.25jm.cc/127.0.0.2:443）：\n    // www.25jm.cc 的 DNS 被污染成 127.0.0.2，而**裸域 25jm.cc 实测 200 / 约 54KB 正常**。\n    // 所以主线路改用裸域（不用 www.）。\n    const val CO36_HOME = "https://25jm.cc"\n\n    /**\n     * 36co 这一族的根域。\n     *\n     * 为什么要有它：站方换域名后，本文件里原先散落的 `rootDomain(u) == "36co"` 判定会**全部失配** ——\n     * 表现为「卡片进不了介绍页 / 介绍页按钮不对 / 板块名认不出」。\n     * 把根域收成一个集合（照 [gxRoots] 的先例），以后再加备用域名只改这一处。\n     */\n    private val co36Roots = setOf("36co", "25jm", "91gc")'),
            # 69c. isCo36Url 改用 co36Roots
            ('    fun isCo36Url(u: String): Boolean =\n        rootDomain(u) == "36co" && Regex("""^/index\\.php/vod/play/id/\\d+/sid/\\d+/nid/\\d+\\.html""")\n            .containsMatchIn(pathOnly(u))', '    fun isCo36Url(u: String): Boolean =\n        rootDomain(u) in co36Roots && Regex("""^/index\\.php/vod/play/id/\\d+/sid/\\d+/nid/\\d+\\.html""")\n            .containsMatchIn(pathOnly(u))'),
            # 69d. maccms 排除改用 co36Roots
            ('        if (rootDomain(u) == "36co") return false', '        if (rootDomain(u) in co36Roots) return false'),
            # 69e. boardLabelFor 改用 co36Roots
            ('            r == "36co" -> CO36_NAME', '            r in co36Roots -> CO36_NAME'),
            # 69f. 家族样本改用可用域名
            ('        "http://www.36co.cc/index.php/vod/play/id/38936/sid/1/nid/1.html",', '        "https://www.25jm.cc/index.php/vod/play/id/38936/sid/1/nid/1.html",'),
            # 69g. 对远端目录里的 36co 做域名纠正（站点列表 UI 那条路）
            ('    fun otherSites(): List<X99Site> {\n        val cat = sites.filterNot { it.name.contains("hanime", ignoreCase = true) }\n        val extra = builtinSites.filterNot { b -> cat.any { it.name.equals(b.name, ignoreCase = true) } }\n        return extra + cat\n    }', '    fun otherSites(): List<X99Site> {\n        val cat = sites.filterNot { it.name.contains("hanime", ignoreCase = true) }\n            // 第 69 轮：**对远端目录里的 36co 做域名纠正**。\n            //\n            // 为什么必须在这里做：站点表来自远端目录 `x99dh.cc`（联网轮询 + 本地缓存 6 小时），\n            // 目录里 36co 仍写着**已整站失效的 www.36co.cc**。\n            // 而下面那行 `filterNot` 是「目录收录了同名站就以目录为准」—— 也就是说，\n            // **内置表里把 CO36_HOME 改对也没用**：只要目录里有 36co，内置那条就被整个丢掉，\n            // 用户看到的仍是目录里的失效域名（本轮真机实测：升级后依旧 Failed to connect www.36co.cc）。\n            //\n            // 所以在这里做客户端纠正：把 36co 的线路换成实测可用的域名，目录修好之前一直有效。\n            // 第 136 轮（用户用浏览器嗅探给出各板块真实直链）：**把实测可用的线路前置**。\n            // 这些板块（肉视频 / rouAV / 好色TV / 黄色仓库 / 321AV）都来自远端目录，\n            // 目录里的域名过期后页面打不开或解析不出播址；同名条目以目录为准，改 builtinSites 无效，\n            // 所以在客户端把实测可用域名插到线路表最前面（不删原有线路，避免误伤）。\n            val fixed = cat.map { s ->\n                val c = if (s.name.equals(CO36_NAME, ignoreCase = true)) co36Fixed(s) else s\n                boardLineFix(c)\n            }\n        val extra = builtinSites.filterNot { b -> fixed.any { it.name.equals(b.name, ignoreCase = true) } }\n        return extra + fixed\n    }\n\n    /**\n     * 把（可能来自远端目录的）36co 站点纠正为**实测可用的域名**。\n     *\n     * 规则：保留名字与描述，线路**只留可用域名**（25jm 主 / 91gc 备），\n     * 并**剔除已失效域名**（含 36co.cc 的任何写法）—— 剔除很关键：\n     * [selectedLine] 会优先返回用户**已保存的线路**，只要失效域名还在候选列表里，\n     * 旧版用户存过的旧值就会被一直命中，表现为「升级了也打不开」。\n     */\n    /**\n     * **用户实测可用的入口线路**（第 136 轮）。\n     *\n     * 来源：用户用浏览器嗅探给出各板块的真实直链。据此逐条实测出这些**能解析出播址**的入口域名：\n     *   · rouAV / 肉视频 : rou666.net（实测 详情页 -> /api/hls 派发口 -> 真 m3u8，63 分片）\n     *   · 好色TV        : hsex1.sbs / hsex01.net（列表 video-N.htm -> video_url -> m3u8）\n     *   · 黄色仓库      : www.hsck.nl（play 页 -> video_url -> m3u8）\n     * 实测**不可用**的同类域名：rou123.ws/org（打不开）、pb365.nl（列表无 video-N.htm）。\n     */\n    private val BOARD_LINE_FIX: Map<String, List<String>> = mapOf(\n        "rouAV" to listOf("https://rou123.vip", "https://rou666.net", "https://rouxxx.cc"),\n        "肉视频" to listOf("https://rou123.vip", "https://rou666.net", "https://rouxxx.cc"),\n\n        "好色TV" to listOf("https://hsex1.sbs", "https://hsex01.net"),\n        "黄色仓库" to listOf("https://www.hsck.nl"),\n    )\n\n    /** 把实测可用线路**前置**到该板块（已有的保留在后，不删）。 */\n    private fun boardLineFix(s: X99Site): X99Site {\n        // 第 142 轮：把「已知失效」的域名从候选里剔除。\n        // 真机实测（2026-10-29）：www.svt75lf.vip 与 www.wpiemmt.vip 连续 0/3 失败，\n        // 而 www.wpiemmt.vip 会 302 跳到 svt75lf —— 那一次请求要卡 19.9 秒（日志第 39/40 行）。\n        // 这类域名留着只会让「自动选最快线路」白等，直接不进候选。\n        val dead = setOf("svt75lf.vip", "wpiemmt.vip")\n        val live = s.lines.filterNot { ln -> dead.any { ln.url.lowercase().contains(it) } }\n        val base = if (live.isEmpty()) s.lines else live\n        val add = BOARD_LINE_FIX.entries.firstOrNull { e ->\n            s.name.equals(e.key, ignoreCase = true) || s.name.contains(e.key, ignoreCase = true)\n        }?.value ?: emptyList<String>()\n        val cur = base.map { it.url.trimEnd(\'/\').lowercase() }\n        val fresh = add.filterNot { e -> cur.any { it == e.lowercase() } }\n        if (fresh.isEmpty()) return s.copy(lines = base)\n        return s.copy(lines = fresh.map { X99Line(it, "") } + base)\n    }\n\n    private fun co36Fixed(s: X99Site): X99Site {\n        val good = listOf(X99Line(CO36_HOME, ""), X99Line("https://www.91gc.pro", ""))\n        val keep = s.lines.filterNot { line -> co36Dead(line.url) }\n        return X99Site(\n            name = s.name,\n            desc = s.desc.ifBlank { "麻豆网 36co · 18 家传媒分区（介绍页 + 网页播放）" },\n            url = CO36_HOME,\n            lines = (good + keep.filterNot { k -> good.any { it.url == k.url } }).distinctBy { it.url },\n        )\n    }\n\n    /** 36co 已确认失效的域名（第 69 轮：主域整站不可达；用户后来给了可用的备用域名）。 */\n    private fun co36Dead(u: String): Boolean {\n        val h = runCatching { URI(u).host.orEmpty() }.getOrDefault("").lowercase()\n        return h == "www.36co.cc" || h == "36co.cc"\n    }'),
