            ('            val list = decodeCatalog(getHtmlLoose(CATALOG_URL))', '            // 第 70 轮：用**当前选中的板块源**（用户可在「设置 → 板块源」手动切换；不自动切）\n            val src = catalogSource()\n            val list = decodeCatalog(getHtmlLoose(src))\n            catalogSourceOk = src'),
            # 70c. catalogSource/setCatalogSource + 连通性检测（判据＝能解出目录，不只看状态码）
            ('    @Volatile\n    var catalogError: String = ""\n        private set', '    @Volatile\n    var catalogError: String = ""\n        private set\n\n    /** 第 70 轮：最近一次**成功解出目录**的板块源（界面上标「当前」用）。 */\n    @Volatile\n    var catalogSourceOk: String = ""\n        private set\n\n    /**\n     * 当前板块源（用户在「设置 → 板块源」里**手动**选的；没选过就用第一条）。\n     *\n     * **刻意不做自动切换**（用户明确要求手动）：只做「检测 + 提示」，选哪条由用户点。\n     */\n    fun catalogSource(): String {\n        val saved = runCatching { setting(KEY_CATALOG_SOURCE, "") }.getOrDefault("")\n        return CATALOG_SOURCES.firstOrNull { it == saved } ?: CATALOG_SOURCES.first()\n    }\n\n    /** 记录用户选的板块源；同时作废目录缓存，让下一次加载立刻用它。 */\n    fun setCatalogSource(url: String) {\n        if (url !in CATALOG_SOURCES) return\n        putSetting(KEY_CATALOG_SOURCE, url)\n        catalogAt = 0L              // 换源必须重取，否则还会拿上一源的缓存\n        catalogSourceOk = ""\n    }\n\n    /**\n     * 板块源的连通性检测结果。\n     * @param url 源地址\n     * @param ms  耗时毫秒；-1 = 不通\n     * @param sites 解出的站点条数（0 = 通了但目录不可解析）\n     */\n    data class SourceProbe(val url: String, val ms: Long, val sites: Int) {\n        val ok: Boolean get() = ms >= 0 && sites > 0\n    }\n\n    /**\n     * 检测**单个板块源**的连通性。\n     *\n     * 判据是「**能解出目录**」而不是 HTTP 状态码 —— 实测这三个源都会回 HTTP 500\n     * 但正文完全正常（82432 B + encodedData），只看状态码会把它们全判成不通。\n     */\n    fun probeCatalogSource(url: String): SourceProbe {\n        val t0 = System.currentTimeMillis()\n        return try {\n            val html = getHtmlLoose(url)\n            val n = decodeCatalog(html).size\n            SourceProbe(url, System.currentTimeMillis() - t0, n)\n        } catch (t: Throwable) {\n            SourceProbe(url, -1L, 0)\n        }\n    }\n\n    /** 并发检测全部板块源（界面「检测连通性」按钮用）。 */\n    fun probeAllCatalogSources(): List<SourceProbe> {\n        val pool = java.util.concurrent.Executors.newFixedThreadPool(CATALOG_SOURCES.size)\n        return try {\n            val fs = CATALOG_SOURCES.map { u -> pool.submit(java.util.concurrent.Callable { probeCatalogSource(u) }) }\n            fs.mapNotNull { runCatching { it.get() }.getOrNull() }\n        } finally {\n            pool.shutdown()\n        }\n    }'),
