            ('            http.newCall(req).execute().use { resp ->\n                val body = resp.body?.string().orEmpty().trim()\n                val el = System.currentTimeMillis() - t0\n                if (body == "ok") (el / 2.5).toLong() else -1\n            }', '            http.newCall(req).execute().use { resp ->\n                val body = resp.body?.string().orEmpty().trim()\n                val el = System.currentTimeMillis() - t0\n                // 第 70 轮：**不只认 "ok" 约定**。\n                //\n                // 原判据 `body == "ok"` 是 x99dh 目录里那条 status.html 的约定；\n                // 对**非 x99dh 一族**的站点（如 36co 的 maccms 首页）正文永远不是 "ok"，\n                // 于是 `testLine` 恒返回 -1 —— 表现为「优选弹窗里这两条线路永远显示不通」，\n                // 而用户明确要求「主域名和备用域名落实到优选弹窗路线里，**带测速**」。\n                //\n                // 现在的判据：HTTP 成功 + 正文非空且不像 Cloudflare 拦截页 ⇒ 通。\n                // （仍保留 "ok" 快速路径；失败一律 -1。）\n                val ok = resp.isSuccessful && body.isNotEmpty() && !cfBlockRe.containsMatchIn(body)\n                if (ok) (el / 2.5).toLong().coerceAtLeast(1L) else -1\n            }'),
            # 71. ★ 从下载 sidecar 重建本地收藏（事故恢复：pm clear 后 hplay_favorites.tsv 丢失）
            ('    fun isFav(url: String): Boolean = url.isNotEmpty() && favs().any { it.url == url }', '    fun isFav(url: String): Boolean = url.isNotEmpty() && favs().any { it.url == url }\n\n    /**\n     * **从已下载产物的 sidecar 重建本地收藏**（第 71 轮，事故恢复用）。\n     *\n     * 起因：`pm clear` / 重装会把应用私有目录整个抹掉，`hplay_favorites.tsv` 随之消失，\n     * 用户的「本站收藏」一条不剩 —— 而下载的视频文件与它们的 `*.detail.json` 还在外部存储里。\n     * detail.json 里就写着 video.url / title / 板块 / 封面，**足够把收藏条目重建出来**。\n     *\n     * 诚实边界（必须让用户知道）：\n     *  · **只能恢复「下载过的」那些**；当初收藏但没下载的，sidecar 里没有依据，无法找回；\n     *  · 已存在的条目不会重复添加（按 url 去重），所以随时可安全再跑一次。\n     *\n     * @param entries 由下载层提供的候选（url / title / thumb / board）\n     * @return 实际新增的条数\n     */\n    fun restoreFavsFrom(entries: List<FavItem>): Int {\n        if (entries.isEmpty()) return 0\n        val existing = favs()\n        val known = existing.map { it.url }.toHashSet()\n        val add = entries.filter { it.url.isNotBlank() && known.add(it.url) }\n        if (add.isEmpty()) return 0\n        val next = (existing + add).sortedByDescending { it.at }\n        runCatching {\n            favFile.parentFile?.mkdirs()\n            favFile.writeText(\n                next.joinToString("\\n") {\n                    "${it.url}\\t${it.title.replace("\\t", "\\\\t").replace("\\n", "\\\\n")}" +\n                        "\\t${it.thumb}\\t${it.board}\\t${it.at}"\n                } + "\\n",\n            )\n        }\n        favsCache = next\n        return add.size\n    }'),
