            # 72e. ★ 36co 失效域名归一到可用主域（用户要求：收藏页 36co 条目要导向可访问的介绍页）
            ('    private val co36Roots = setOf("36co", "25jm", "91gc")', '    private val co36Roots = setOf("36co", "25jm", "91gc")\n\n    /**\n     * 把 36co 家族的**失效域名**换成当前可用的主域（第 72 轮，用户要求）。\n     *\n     * 起因：用户收藏页里 36co 的条目，url 是**当年下载时**存下的（例如已整站不可达的\n     * `www.36co.cc`），点开自然是打不开的域名。用户原话：\n     * 「收藏页面 36co 下载的视频，url 链接修复导向**可访问的域名**介绍页」。\n     *\n     * 规则：**只把 host 换成 [CO36_HOME] 的 host，路径与查询串原样保留** ——\n     * 同一套库换域名后路径是稳定的，这样就能落到同一部片子的介绍页。\n     * 非 36co 家族的 url 一律原样返回（不碰别的站）。\n     */\n    fun co36ReviveUrl(u: String): String {\n        if (u.isBlank()) return u\n        val root = runCatching { rootDomain(u) }.getOrDefault("")\n        if (root !in co36Roots) return u\n        // 已经是可用主域就不用动（避免无谓重建 URL）\n        val host = runCatching { URI(u).host.orEmpty() }.getOrDefault("")\n        val homeHost = runCatching { URI(CO36_HOME).host.orEmpty() }.getOrDefault("")\n        if (host == homeHost) return u\n        return runCatching {\n            val p = URI(u)\n            java.net.URI(\n                p.scheme ?: "https", null, homeHost,\n                if (p.port > 0) p.port else -1, p.path, p.query, p.fragment,\n            ).toString()\n        }.getOrDefault(u)\n    }'),
            # 73a. ★ favs() 读取时归一 36co 域名（修「收藏页域名还是旧的」）
            ('                        out.add(\n                            FavItem(\n                                url = f[0],\n                                title = f[1].replace("\\\\t", "\\t").replace("\\\\n", "\\n"),\n                                thumb = f[2],\n                                board = f[3],\n                                at = f[4].toLongOrNull() ?: 0L,\n                            ),\n                        )', '                        out.add(\n                            FavItem(\n                                // 第 73 轮（用户报「36co 的收藏页域名还是旧的」）：\n                                //\n                                // 收藏文件里存的是**入藏当时**的 url。36co 换过域名，\n                                // 老条目（尤其是第 71 轮从 sidecar 还原进来的那批）留着已失效的\n                                // www.36co.cc，点开自然打不开。\n                                // 上一轮只在「读 sidecar」时做了归一，**漏了「读收藏文件」这条**；\n                                // 现在在**读取时**统一过一遍 —— 这样连**已保存的旧收藏**也被修正，\n                                // 且不必改写用户的收藏文件（下次写入时自然落成新域名）。\n                                url = co36ReviveUrl(f[0]),\n                                title = f[1].replace("\\\\t", "\\t").replace("\\\\n", "\\n"),\n                                thumb = f[2],\n                                board = f[3],\n                                at = f[4].toLongOrNull() ?: 0L,\n                            ),\n                        )'),
            # 74b. ★ hanimeSite()/sitesWithHanime()：优选弹窗站点表补上本命板块（原来 otherSites 刻意排除它）
            ('    /** 除本命板块（Hanime1）以外的站点，供「站点合集」板块使用（含内置站点）。 */', '    /**\n     * **本命板块（Hanime1）的站点对象**，供「优选访问」弹窗使用（第 74 轮，用户要求）。\n     *\n     * 为什么需要它：`sites` 是远端目录（x99dh.cc）里那批站点，目录里**没有 Hanime1** ——\n     * 「本命板块」是本应用内置的概念（见 [HANIME_SITE]）。\n     * 于是从主页点 hanime1.me 打开优选弹窗时，站点表里找不到它，\n     * 弹窗只显示站点合集那些站，**看不到 hanime 自己的优选线路**\n     *（用户原话：「优选路线里只有本命 hanime，没有 hanime 的优选路线了」）。\n     *\n     * 线路来源：**只用目录里真实存在的 hanime1 线路**（将来目录收录/更新就自动生效）——\n     * 这里**不编造镜像域名**：与其塞几个没验证过的地址让用户点到打不开的线路，\n     * 不如只给确实可用的。目录没有镜像时，弹窗就只显示「官方源」一条（这也正是默认行为）。\n     */\n    fun hanimeSite(): X99Site {\n        val fromCatalog = sites.firstOrNull { it.name.equals(HANIME_SITE, true) }?.lines.orEmpty()\n        // ★★ 第 332 轮（用户要求）：内置备用页面域也要能切、且都能登录。\n        //\n        // 参考 Han1meViewer 的 Preferences.baseUrl 与站点切换弹窗：它把官方域与几个\n        // 备用域并列成一组站点，用户自由切换，登录态跟着域走。\n        // 这里照同样做法，但只用实测可用的域 —— 编造域名只会让用户点到打不开的线路。\n        val builtin = BACKUP_HANIME.map { X99Line(it, it + "/") }\n        val lines = (listOf(X99Line(OFFICIAL_HANIME, OFFICIAL_HANIME + "/")) + builtin + fromCatalog)\n            .distinctBy { it.url }\n        return X99Site(\n            name = HANIME_SITE,\n            desc = "hanime1.me 官方源与优选镜像（官方源可登录，DoH/代理等网络功能只对它生效）",\n            url = OFFICIAL_HANIME,\n            lines = lines,\n        )\n    }\n\n    /**\n     * 站点表里**确保含本命板块**，并把它放在首位（第 74 轮）。\n     *\n     * 原本各处都用 `otherSites()`（**刻意排除 hanime**，因为那是"站点合集"板块用的）。\n     * 但「优选访问」弹窗需要**两套都能选**：既要有站点合集，也要有本命板块自己的线路。\n     * 所以弹窗走这个函数：本命板块在前，其余站点照旧。\n     */\n    fun sitesWithHanime(): List<X99Site> {\n        val rest = otherSites().filterNot { it.name.equals(HANIME_SITE, true) }\n        return listOf(hanimeSite()) + rest\n    }\n\n    /** 除本命板块（Hanime1）以外的站点，供「站点合集」板块使用（含内置站点）。 */'),
            # 74g. ★ 新番预告：站方入口已改 /previews/yyyyMM 且版式不同（原 search?genre= 恒空）——照 Han1meViewer 参考实现补全
            ('    /** 镜像列表/搜索页（/search?query=xx&page=N）卡片。 */', '    // ---------- 新番预告（/previews/yyyyMM） ----------\n    //\n    // 第 74 轮（用户要求「官方源新番预告这里修复下，现在没有获取到内容」）。\n    //\n    // ## 根因（本轮真机 + 源码双向确认）\n    //  ① **入口错了**：应用把「新番預告」页签指向 `search?genre=新番預告`，\n    //     但站方早已把它改成独立页 `previews/YYYYMM`（站点 nav 里就是 /previews/202610）。\n    //     实测：`search?genre=新番預告` 回 200 但**一张卡片都没有**（连 genre=裏番 也是 0 张）。\n    //  ② **版式不同**：预告页根本没有 `video-item-container`，\n    //     所以 `parseCards()`（首页/搜索页那套）在它上面必然解析出空列表。\n    //     它用的是 `content-padding` / `preview-info-cover` / `preview-info-content-padding` /\n    //     `single-video-tag` / `preview-image-modal-trigger` 这套**预告专用**结构。\n    //\n    // ## 参考实现\n    //  照 `W\\临时\\avp_h1v_src\\Han1meViewer-main`（用户提供的参考源码）的\n    //  `Parser.hanimePreview()` 与 `PreviewUtils` 做的：\n    //   · 端点 `GET previews/{yyyyMM}`，月份码 = `%04d%02d`；\n    //   · 上一月/下一月用 [shiftMonthCode] 移位；\n    //   · 每个条目从 `div[class=content-padding] > div` **两两成对**取：\n    //     奇数位＝封面/标题/厂商/发售日，偶数位＝简介/标签/预览图。\n    //\n    // ## 诚实边界\n    //  · 站方**近几个月的预告页自身 500**（实测 2026-05 起连续 500，而 202603/202604/202512/202601 均 200）。\n    //    这不是本应用的 bug —— 所以要把「服务端错误」与「解析不出来」在界面上分开说，\n    //    并让用户能翻到有数据的月份。\n    //\n    // ## 为什么不用 Jsoup\n    //  本模块依赖只有 OkHttp + kotlinx.coroutines（见 HanimeClient 的 import），\n    //  引入 Jsoup 会动构建依赖；这里的结构简单且稳定，用正则解析足够，**不动依赖**。\n\n    /** 预告条目（一个「新番预告」影片）。字段对齐参考实现的 PreviewInfo。 */\n    data class PreviewItem(\n        /** 片名（日文/原文）。 */\n        val title: String,\n        /** 中文/译名标题（preview-info-content-padding 里的 h4）。 */\n        val videoTitle: String,\n        val cover: String,\n        val introduction: String,\n        val brand: String,\n        val releaseDate: String,\n        /** 预告页锚 id；有对应正片时可跳到 /watch?v=<code>。 */\n        val videoCode: String,\n        val tags: List<String>,\n        val relatedPics: List<String>,\n    )\n\n    /** 一整页预告（含月份导航状态）。 */\n    data class PreviewPage(\n        val monthCode: String,\n        val items: List<PreviewItem>,\n        /** 站方是否给了「上一月」入口。 */\n        val hasPrev: Boolean,\n        val hasNext: Boolean,\n        /** 非空 = 这一页取不到（HTTP 错误 / 解析为空），内容是给人看的理由。 */\n        val error: String,\n    )\n\n    /** 月份码 `yyyyMM`（照参考实现 currentCodeFrom）。 */\n    fun monthCodeOf(year: Int, month: Int): String = String.format("%04d%02d", year, month)\n\n    /** 本月月份码。 */\n    fun currentMonthCode(): String {\n        val now = java.util.Calendar.getInstance()\n        return monthCodeOf(now.get(java.util.Calendar.YEAR), now.get(java.util.Calendar.MONTH) + 1)\n    }\n\n    /**\n     * 月份码按 delta 个月移位（照参考实现 shiftMonthCode）。\n     * delta 为负＝往更早的月份走。跨年自动处理。\n     */\n    fun shiftMonthCode(code: String, delta: Int): String {\n        if (code.length != 6) return code\n        var y = code.substring(0, 4).toIntOrNull() ?: return code\n        var m = (code.substring(4, 6).toIntOrNull() ?: return code) + delta\n        while (m < 1) { m += 12; y -= 1 }\n        while (m > 12) { m -= 12; y += 1 }\n        return monthCodeOf(y, m)\n    }\n\n    /** 月份码 → 界面标签（如 202604 → 2026/4）。 */\n    fun monthLabel(code: String): String {\n        if (code.length != 6) return code\n        val y = code.substring(0, 4); val m = code.substring(4, 6).toIntOrNull() ?: return code\n        return "$y/$m"\n    }\n\n    /** 预告页地址。 */\n    fun previewUrl(homeUrl: String, monthCode: String): String =\n        (if (homeUrl.isBlank()) OFFICIAL_HANIME else originOf(homeUrl)) + "/previews/" + monthCode\n    /**\n     * 抓取并解析某个月的「新番预告」。\n     *\n     * @param homeUrl 官方源留空；优选镜像传站点 origin\n     * @param monthCode yyyyMM\n     * @return 永不为 null：取不到时 [PreviewPage.error] 里是**人话原因**（界面据此如实显示）\n     */\n    fun loadPreview(homeUrl: String, monthCode: String): PreviewPage {\n        val url = previewUrl(homeUrl, monthCode)\n        val html = runCatching { getHtml(url) }.getOrElse { t ->\n            return PreviewPage(monthCode, emptyList(), false, false, "请求失败：${t.message ?: t}")\n        }\n        // 站方对**没有预告的月份**会直接抛 500（实测 2026-05 起连续如此）。\n        // 这时页面是 Laravel 的 "Server Error"，没有预告结构 —— 要**如实区分**，\n        // 而不是让用户以为「本应用坏了」。\n        if (html.contains("Server Error") && !html.contains("preview-info-cover")) {\n            return PreviewPage(monthCode, emptyList(), true, true,\n                "站方这一页暂时出错（Server Error）：${monthLabel(monthCode)} 的预告页在 hanime1.me 上是 500。" +\n                    "可翻到相邻月份看看，或稍后再来。")\n        }\n        val items = parsePreviewItems(html)\n        val hasPrev = Regex("""hidden-md hidden-lg""").find(html) != null && html.contains("left")\n        val hasNext = Regex("""hidden-md hidden-lg""").find(html) != null && html.contains("right")\n        val err = if (items.isEmpty()) "这一页没有解析到预告条目（${monthLabel(monthCode)}）" else ""\n        return PreviewPage(monthCode, items, hasPrev, hasNext, err)\n    }\n\n    /**\n     * 解析预告页的条目列表。\n     *\n     * 结构（照参考实现 `Parser.hanimePreview`）：\n     *  `div[class=content-padding] > div` 里的子 div **两两成对** ——\n     *  第 1 个＝封面块（id 即 videoCode、h4 标题、preview-info-cover>img、\n     *            preview-info-content-padding 里的 h4/h5 给译名与厂商/发售日），\n     *  第 2 个＝详情块（h5 简介、single-video-tag>a 标签、preview-image-modal-trigger 预览图）。\n     */\n    private fun parsePreviewItems(html: String): List<PreviewItem> {\n        // 只取 content-padding 区块，避免把页面别处的 div 也当成条目\n        val block = runCatching {\n            val i = html.indexOf("content-padding")\n            if (i < 0) "" else html.substring(i)\n        }.getOrDefault("")\n        if (block.isEmpty()) return emptyList()\n        // 逐个「顶层 div」切分：以带 id 的预告卡为界（id 就是 videoCode）\n        val idRe = Regex("""<div\\s+id="(\\d{3,})"""")\n        val marks = idRe.findAll(block).toList()\n        if (marks.isEmpty()) return emptyList()\n        val out = ArrayList<PreviewItem>()\n        for ((k, m) in marks.withIndex()) {\n            val start = m.range.first\n            val end = if (k + 1 < marks.size) marks[k + 1].range.first else block.length\n            val seg = block.substring(start, end)\n            val code = m.groupValues[1]\n            // 封面：preview-info-cover 里的 img\n            val cover = Regex("""preview-info-cover[^>]*>\\s*<img[^>]*src="([^"]+)"""")\n                .find(seg)?.groupValues?.get(1)?.replace("&amp;", "&").orEmpty()\n            // 内容块：preview-info-content-padding\n            val contentSeg = Regex("""preview-info-content-padding[\\s\\S]{0,2500}""").find(seg)?.value.orEmpty()\n            val h4s = Regex("""<h4[^>]*>([\\s\\S]{0,200}?)</h4>""").findAll(contentSeg)\n                .map { clean(it.groupValues[1]) }.filter { it.isNotEmpty() }.toList()\n            val h5s = Regex("""<h5[^>]*>([\\s\\S]{0,300}?)</h5>""").findAll(contentSeg)\n                .map { it.groupValues[1] }.toList()\n            val videoTitle = h4s.firstOrNull().orEmpty()\n            val brand = runCatching {\n                Regex("""<h5[^>]*>\\s*<a[^>]*>([\\s\\S]{0,80}?)</a>""").find(contentSeg)\n                    ?.groupValues?.get(1)?.let { clean(it) }\n            }.getOrNull().orEmpty().ifBlank {\n                clean(h5s.firstOrNull().orEmpty())\n            }\n            val releaseDate = clean(h5s.getOrNull(1).orEmpty())\n            // 标题：优先 hidden 的那个 h4（原文名），否则第一个 h4\n            val rawTitle = Regex("""<h4[^>]*hidden[^>]*>([\\s\\S]{0,200}?)</h4>""")\n                .find(seg)?.groupValues?.get(1)?.let { clean(it) }.orEmpty().ifBlank { videoTitle }\n            val introduction = Regex("""<h5[^>]*>([\\s\\S]{0,600}?)</h5>""")\n                .find(seg.substringAfter("</h4>", ""))?.groupValues?.get(1)?.let { clean(it) }.orEmpty()\n            val tags = Regex("""single-video-tag[^>]*>\\s*<a[^>]*>([\\s\\S]{0,60}?)</a>""")\n                .findAll(seg).map { clean(it.groupValues[1]) }.filter { it.isNotEmpty() }.toList().distinct()\n            val pics = Regex("""<img[^>]*class="preview-image-modal-trigger"[^>]*src="([^"]+)"""")\n                .findAll(seg).map { it.groupValues[1].replace("&amp;", "&") }.toList()\n            out.add(\n                PreviewItem(\n                    title = rawTitle, videoTitle = videoTitle, cover = cover,\n                    introduction = introduction, brand = brand, releaseDate = releaseDate,\n                    videoCode = code, tags = tags, relatedPics = pics,\n                ),\n            )\n        }\n        return out.distinctBy { it.videoCode }\n    }\n\n    /** 去 HTML 标签与实体，压空白（预告页文字里混着 &nbsp; 之类）。 */\n    private fun clean(s: String): String = s\n        .replace(Regex("""<[^>]+>"""), " ")\n        .replace("&nbsp;", " ").replace("&amp;", "&").replace("&quot;", "\\"")\n        .replace("&#39;", "\\u0027").replace("&lt;", "<").replace("&gt;", ">")\n        .replace(Regex("""\\s+"""), " ")\n        .trim()\n    /** 镜像列表/搜索页（/search?query=xx&page=N）卡片。 */'),
            # 74o. ★ loadPreview 网络路径分家：官方源走 HanimeClient，镜像才走 X99.getHtml
            ('    fun loadPreview(homeUrl: String, monthCode: String): PreviewPage {\n        val url = previewUrl(homeUrl, monthCode)\n        val html = runCatching { getHtml(url) }.getOrElse { t ->\n            return PreviewPage(monthCode, emptyList(), false, false, "请求失败：${t.message ?: t}")\n        }', '    fun loadPreview(homeUrl: String, monthCode: String): PreviewPage {\n        val url = previewUrl(homeUrl, monthCode)\n        // ★ 网络路径要分家（第 74 轮真机踩到）：\n        //   · **官方源**（homeUrl 空）必须走 `HanimeClient` —— 它对 hanime1.me 配了\n        //     专用边缘节点 + DoH；用 X99 那套（只为板块站解析）会走污染 DNS，\n        //     真机报 `failed to connect to hanime1.me:443`。\n        //   · **优选镜像**才用 X99 的 getHtml（它本来就是给镜像站用的）。\n        val html = runCatching {\n            if (homeUrl.isBlank()) HanimeClient.previewHtml(monthCode) else getHtml(url)\n        }.getOrElse { t ->\n            return PreviewPage(monthCode, emptyList(), false, false, "请求失败：${t.message ?: t}")\n        }'),
            # 83a. ★★ 优选镜像详情解析 mirrorDetail（sources + 按当前站点推导的标签）
            ('    fun mirrorListing(url: String): List<HanimeVideo> = HanimeClient.parseCards(getHtml(url))', '    fun mirrorListing(url: String): List<HanimeVideo> = HanimeClient.parseCards(getHtml(url))\n    fun mirrorDetail(v: HanimeVideo): HanimeDetail? {\n        val html = runCatching { getHtml(v.url, referer = originOf(v.url) + "/") }.getOrNull() ?: return null\n        if (html.length < 200) return null\n        // 画质/直链：官方结构 source src / type=video/mp4 / size=数字\n        // 用 Kotlin **原始字符串**（三引号）：正则里的反斜杠不必二次转义，可读且不易写错。\n        val srcRe = Regex("""<source\\s+src="([^"]+)"[^>]*type="video/mp4"[^>]*size="(\\\\d+)"""")\n        // 注意括号：a ?: 0 to b 会被解析成 a ?: (0 to b)（类型跑偏成 Serializable），须写 (a ?: 0) to b。\n        val sources: List<Pair<Int, String>> = srcRe.findAll(html)\n            .map { (it.groupValues[2].toIntOrNull() ?: 0) to it.groupValues[1].replace("&amp;", "&") }\n            .toList()\n            .sortedByDescending { it.first }\n        // 兜底：页内任意 mp4 直链（有些镜像把 source 写成别的形态）\n        val mp4Re = Regex("""https?://[^"\'\\s]+\\.mp4[^"\'\\s]*""")\n        val allSources: List<Pair<Int, String>> = if (sources.isNotEmpty()) sources else mp4Re\n            .findAll(html).map { it.value.replace("&amp;", "&") }.distinct().take(6).map { 0 to it }.toList()\n        fun metaOf(prop: String) = Regex("<meta" + "\\\\s+" + "property=" + "\\"" + prop + "\\"" + "\\\\s+" + "content=\\"([^\\"]*)\\"").find(html)?.groupValues?.get(1)\n        val title = metaOf("og:title")?.let { unescape(it) }.orEmpty()\n        val desc = metaOf("og:description")?.let { unescape(it) }.orEmpty()\n        val cover = metaOf("og:image")?.replace("&amp;", "&") ?: v.thumb\n        // 标签：按**当前站点的 host** 匹配 /tag/ 链接\n        //（官方版本把域名写死成 hanime1.me，镜像页因此一个标签都取不到）\n        val host = runCatching { java.net.URI(v.url).host.orEmpty() }.getOrDefault("")\n        val tagRe = if (host.isBlank()) {\n            Regex("href=\\"[^\\"]*/tag/[^\\"]*\\"[^>]*>" + "\\\\s*" + "([^<]+?)" + "\\\\s*" + "<")\n        } else {\n            Regex("href=\\"https?://" + Regex.escape(host) + "/tag/[^\\"]*\\"[^>]*>" + "\\\\s*" + "([^<]+?)" + "\\\\s*" + "<")\n        }\n        val tags = tagRe.findAll(html).map { unescape(it.groupValues[1]).trim() }\n            .filter { it.isNotEmpty() }.distinct().take(12).toList()\n        val related = runCatching { parseGeneric(v.url, html) }.getOrDefault(emptyList())\n            .filter { it.thumb.isNotBlank() && sameShape(it.url, v.url) && !sameWork(it.url, v.url) }\n            .distinctBy { it.url }.take(18)\n        // 一个都没解析到 ⇒ 返回 null 让上层回落（不假装成功）\n        if (title.isBlank() && allSources.isEmpty()) return null\n        return HanimeDetail(\n            video = v.copy(title = title.ifBlank { v.title }, thumb = cover),\n            description = desc,\n            tags = tags,\n            sources = allSources,\n            related = related,\n            isFav = false,\n            isSaved = false,\n            saveListId = "",\n        )\n    }'),
            # 83b. ★★ 提速：连接超时 12s→7s（三次元点开 20 秒的根因之一）
            ('    private val http: OkHttpClient by lazy {\n        OkHttpClient.Builder()\n            .proxy(Proxy.NO_PROXY)\n            .connectTimeout(12, TimeUnit.SECONDS)\n            .readTimeout(30, TimeUnit.SECONDS)', '    private val http: OkHttpClient by lazy {\n        OkHttpClient.Builder()\n            .proxy(Proxy.NO_PROXY)\n            // ★ 第 83 轮提速（用户报「三次元板块点开封面到介绍页要 20 秒」）：\n            // 连接超时原为 12s，而 getHtml() 有一次自动重试（失败后还 sleep 1200ms）\n            // —— 最坏 12 + 1.2 + 12 ≈ 25 秒，与实测 20 秒吻合。\n            // 收到 7 秒：可用站点首包通常 2 秒内；连不上的早失败早回落，比干等 12 秒更快出结果。\n            // 读超时保持 30 秒不变（正文大页面不能被误杀）。\n            .connectTimeout(7, TimeUnit.SECONDS)\n            .readTimeout(30, TimeUnit.SECONDS)'),
