            # 83d. ★★ 提速：metaDetailOf(html) + 60 秒正文缓存（同一页面不再抓两次）
            ('    fun metaDetail(v: HanimeVideo): HanimeDetail? {', '    /**\n     * 详情页正文缓存（第 83 轮，为「三次元板块」提速）。\n     *\n     * 用户报：「三次元板块（= 除 han1me 官方站与优选之外的所有板块）点开封面到介绍页要 20 秒」。\n     *\n     * 根因（叠加）：boardPage 原来写作 (boardDetail(v)) ?: metaDetail(v) ——\n     * **两个分支各自去抓同一个页面**，第一家失败后再完整抓一遍；每次又各有重试。\n     *\n     * 修法：同一 URL 的正文 60 秒内复用。于是 boardDetail 拿到的那份 html 可直接喂给\n     * metaDetailOf，**省掉第二次完整抓取**。只缓存正文不缓存解析结果（各入口要的字段不同）。\n     */\n    private val htmlCache = java.util.concurrent.ConcurrentHashMap<String, Pair<Long, String>>()\n\n    /** 取页（带 60 秒短期缓存；失败不写缓存，下次仍会重试）。 */\n    private fun getHtmlCached(url: String): String? {\n        val now = System.currentTimeMillis()\n        htmlCache[url]?.let { (ts, body) -> if (now - ts < 60_000L) return body }\n        val body = runCatching { getHtml(url, referer = originOf(url) + "/") }.getOrNull()\n        if (body != null && body.length >= 200) htmlCache[url] = now to body\n        return body\n    }\n\n    /** 用**已有的** html 解析通用详情（不发网络请求）。 */\n    fun metaDetailOf(v: HanimeVideo, html: String): HanimeDetail? {'),
            # 83d2. ★ 补回 metaDetail 包装（走缓存后交给 metaDetailOf）
            ('    /**\n     * 板块详情入口（**卡片点击只认这一个函数**）：有原生播址的板块沿用 `boardDetail`；', '    /** 兼容旧入口：自己取页（走 60 秒缓存）后交给 metaDetailOf。 */\n    fun metaDetail(v: HanimeVideo): HanimeDetail? {\n        val cachedHtml = getHtmlCached(v.url) ?: return null\n        return metaDetailOf(v, cachedHtml)\n    }\n\n    /**\n     * 板块详情入口（**卡片点击只认这一个函数**）：有原生播址的板块沿用 `boardDetail`；'),
