            # 91a. mirrorRefererFor：优选播放必须带同域 Referer
            ('    fun refererFor(mediaUrl: String): String {', '    /**\n     * **优选镜像播放时该带的 Referer**（第 91 轮真机修）。\n     *\n     * 实测：优选镜像的媒体地址不带 Referer 时，回 **200 + 143 B +\n     * application/vnd.apple.mpegurl**（一个 m3u8 清单），播放器把它当 mp4 ⇒\n     * ERROR_CODE_PARSING_CONTAINER_UNSUPPORTED；带上同域 Referer 才回 206 + video/mp4。\n     *\n     * 取值：优先用「当前选中的优选线路根」（用户就是从那个域点的片），\n     * 没有线路设置时退回媒体自身的域根（同域 Referer 才有效，跨域实测直接 TLS 断连）。\n     * 官方源不走这里（调用方已排除），保持空 Referer。\n     */\n    fun mirrorRefererFor(mediaUrl: String): String {\n        val host = runCatching { URI(mediaUrl).host.orEmpty().lowercase() }.getOrDefault("")\n        if (host.isEmpty()) return ""\n        val line = runCatching { setting("hanime.line", "") }.getOrDefault("")\n        val lineOrigin = if (line.isBlank()) "" else originOf(line)\n        val lineHost = runCatching { URI(lineOrigin).host.orEmpty().lowercase() }.getOrDefault("")\n        // 线路域与媒体域相同 ⇒ 直接用线路根；否则（媒体走轮换域）用媒体自己的域根。\n        return if (lineHost.isNotEmpty() && lineHost == host) "$lineOrigin/" else "https://$host/"\n    }\n\n    fun refererFor(mediaUrl: String): String {'),
            # 91c. 优选标签支持 tags[]= 查询形态
            ('        val tags = tagRe.findAll(html).map { unescape(it.groupValues[1]).trim() }\n            .filter { it.isNotEmpty() }.distinct().take(12).toList()', '        // ★★ 第 91 轮真机修（用户报「官方站没有落实可点击搜索的标签」「优选站标签取不到」）：\n        //\n        // 实测优选镜像的标签**不是 /tag/ 路径**，而是查询参数形态：\n        //   href="…/search?tags%5B%5D=JK"（即 tags[]=JK）\n        // 官方源那套 tagRe 只认 href="https://hanime1.me/tag/…"，于是两边都取不到标签。\n        //\n        // 现在两种形态都认：/tag/<名字> 与 tags[]=<名字>。\n        val tagsPath = tagRe.findAll(html).map { unescape(it.groupValues[1]).trim() }\n        val tagsQuery = Regex("tags(?:%5B%5D|\\\\[\\\\])?=([^&\\"]+)").findAll(html)\n            .map { unescape(java.net.URLDecoder.decode(it.groupValues[1], "UTF-8")).trim() }\n        val tags = (tagsPath + tagsQuery)\n            .filter { it.isNotEmpty() }.distinct().take(12).toList()'),
            # 96a. ★★★ 修正 mirrorRefererFor：必须用镜像线路域（旧逻辑写反 ⇒ 直链仍回 143B m3u8）
            ('    fun mirrorRefererFor(mediaUrl: String): String {\n        val host = runCatching { URI(mediaUrl).host.orEmpty().lowercase() }.getOrDefault("")\n        if (host.isEmpty()) return ""\n        val line = runCatching { setting("hanime.line", "") }.getOrDefault("")\n        val lineOrigin = if (line.isBlank()) "" else originOf(line)\n        val lineHost = runCatching { URI(lineOrigin).host.orEmpty().lowercase() }.getOrDefault("")\n        // 线路域与媒体域相同 ⇒ 直接用线路根；否则（媒体走轮换域）用媒体自己的域根。\n        return if (lineHost.isNotEmpty() && lineHost == host) "$lineOrigin/" else "https://$host/"\n    }', '    fun mirrorRefererFor(mediaUrl: String): String {\n        val host = runCatching { URI(mediaUrl).host.orEmpty().lowercase() }.getOrDefault("")\n        if (host.isEmpty()) return ""\n        // ★★ 第 96 轮真机修（用户报「优选站还是播不了、直链还是 4 秒」）——\n        //    上一版这里的逻辑**写反了**，这是本 bug 的真根因：\n        //\n        //    旧逻辑：线路域 == 媒体域 才用线路根，否则用「媒体自身的域根」。\n        //    但优选镜像的媒体地址是**轮换域**（实测 `jre<hex>.vcmathe.com`），\n        //    与线路域（hanime101.com）**必然不相等** ⇒ 永远走 else ⇒ Referer 成了媒体自身域。\n        //\n        //    逐条实测（同一个 URL）：\n        //      Referer = jre1ig….vcmathe.com（媒体自身域） → 200 + **143 B** + mpegurl ❌\n        //      Referer = www.hanime101.com（**镜像线路域**）  → 200 + 65536 B + video/mp4 ✅\n        //      Referer = hanime101.com（不带 www）           → 200 + 65536 B + video/mp4 ✅\n        //\n        //    结论：**必须用「当前选中的镜像线路域」**，与媒体域是否相同无关。\n        //    线路域拿不到时才退回媒体自身域（至少不是空 Referer）。\n        val line = runCatching { setting("hanime.line", "") }.getOrDefault("")\n        val lineOrigin = if (line.isBlank()) "" else originOf(line)\n        if (lineOrigin.isNotBlank()) return "$lineOrigin/"\n        return "https://$host/"\n    }'),
