            ('    /** 用**已有的** html 解析通用详情（不发网络请求）。 */\n    fun metaDetailOf(v: HanimeVideo, html: String): HanimeDetail? {\n        val html = runCatching { getHtml(v.url, referer = originOf(v.url) + "/") }.getOrDefault("")\n        if (html.length < 200) return null', '    /** 用**已有的** html 解析通用详情（不发网络请求）。 */\n    fun metaDetailOf(v: HanimeVideo, htmlIn: String): HanimeDetail? {\n        // ★★★ 第 101 轮真机修（用户报「介绍页作者头像还是没有」+ 提速）：\n        //\n        // **真 bug**：这个函数的参数名是 `html`，却在第一行又把它**覆盖**成一次新的网络请求：\n        //     fun metaDetailOf(v: HanimeVideo, html: String) {\n        //         val html = runCatching { getHtml(v.url, ...) }   ← 屏蔽了传入的 html！\n        // 后果有两层：\n        //   ① 调用方（boardPage）明明已经用 getHtmlCached 抓过一份正文，\n        //      这里**又完整抓了一遍** —— 白花一次往返（「点封面到介绍页慢」的一个来源）；\n        //   ② 一旦这次重抓失败/超时，`return null` 直接放弃 ——\n        //      调用方手里那份**好端端的正文**被白白浪费，整页退化成"没有作者/没有简介"。\n        //\n        // 修法：**用传入的 html**（这正是函数名 "Of" 与注释「不发网络请求」的本意）；\n        // 只有调用方传空时才回退去抓一次（保留旧行为作为兜底）。\n        val html = if (htmlIn.isNotBlank()) htmlIn\n            else runCatching { getHtml(v.url, referer = originOf(v.url) + "/") }.getOrDefault("")\n        if (html.length < 200) return null'),
