            ('    private val htmlCache = java.util.concurrent.ConcurrentHashMap<String, Pair<Long, String>>()', '    /**\n     * 站内正文缓存（60 秒 TTL）。\n     *\n     * ★ 第 101 轮：加**容量上限**（原来只按时间失效、没有条数上限）。\n     * 每条存的是**整页 HTML**（可达数百 KB），长跑（翻很多板块）会持续增长；\n     * 这里限到 40 条，超出先清掉最旧的一半 —— 既控制内存，也不影响刚看过的页面命中。\n     */\n    private const val HTML_CACHE_MAX = 40\n    private val htmlCache = java.util.concurrent.ConcurrentHashMap<String, Pair<Long, String>>()\n\n    /** 容量兜底：超过上限就按时间清掉较旧的一半（在最旧的调用点调用即可，代价很小）。 */\n    private fun trimHtmlCache() {\n        if (htmlCache.size <= HTML_CACHE_MAX) return\n        val sorted = htmlCache.entries.sortedBy { it.value.first }\n        for (e in sorted.take(sorted.size / 2)) htmlCache.remove(e.key)\n    }'),
            # 110a. ★★★ 修 boardPage 闸门：原实现每次冷开固定空等 8 秒（介绍页 −8.0s/次），且去重语义写反
            ('    fun boardPage(v: HanimeVideo): HanimeDetail? {\n        // 第 59 轮：命中的话直接返回；否则记录 in-flight，并发点击复用同一个请求。\n        boardPageFresh(v.url)?.let { return it }\n        val gate = boardPageGate.computeIfAbsent(v.url) { java.util.concurrent.CountDownLatch(1) }\n        if (gate.count > 0L && boardPageOwner != v.url) {\n            runCatching { gate.await(8, java.util.concurrent.TimeUnit.SECONDS) }\n            boardPageFresh(v.url)?.let { return it }\n        }\n        boardPageOwner = v.url\n        try {\n            // ★ 第 83 轮提速（用户报「三次元板块点开封面到介绍页要 20 秒」；\n            //   三次元 = 除 han1me 官方站与优选之外的所有板块）：\n            //\n            // 原来这里两个分支**各自去抓同一个页面**：boardDetail 失败/超时后，\n            // metaDetail 再完整抓一遍，每次又各自带重试 —— 同页最多抓 4 次。\n            //\n            // 修法：**共享一份正文缓存**（getHtmlCached，60 秒 TTL）：\n            //  · 先照旧试 boardDetail（原生板块能命中就还是一抓即得，**不预抓、不倒退**）；\n            //  · 它失败/不适用时，用缓存抓一次正文交给 metaDetailOf 解析，\n            //    若这份正文已经因上面的 `getHtmlCached` 命中缓存，就连这一次网络都省了。\n            val native = if (isNativeBoardUrl(v.url)) runCatching { boardDetail(v) }.getOrNull() else null\n            val d = native ?: runCatching {\n                val h = getHtmlCached(v.url) ?: return@runCatching null\n                metaDetailOf(v, h)\n            }.getOrNull()\n            if (d != null) boardPageRemember(v.url, d)\n            return d\n        } finally {\n            if (boardPageOwner == v.url) boardPageOwner = ""\n            boardPageGate.remove(v.url)?.countDown()\n        }\n    }\n', '    fun boardPage(v: HanimeVideo): HanimeDetail? {\n        // ★★★ 第 110 轮修 —— 三次元板块介绍页**每次冷开固定空等 8 秒**的真根因。\n        //\n        // 第 59 轮用 computeIfAbsent 取闸门，**分不清「我创建的」和「别人正在飞」**：\n        //   · 冷缓存时它总是返回**本次调用刚创建**的那个 CountDownLatch(1)；\n        //   · 而唯一的 countDown() 就在同一函数的 finally 里 —— 要 await 返回后才执行；\n        //   · boardPageOwner 初值空串、赋值又在 await 之后 ⇒ 那个 if 条件恒真。\n        // ⇒ 等于「join 一个只有自己会放的锁」，必然空等满 8.0 秒才开始发第一条请求。\n        //\n        // 而且去重语义是**反的**：boardPageOwner == v.url（同一 URL 正在抓）时条件为 false，\n        // 反而**跳过等待、直接重复抓取**；boardPageOwner 还是单个全局变量，承担不了按 URL 去重。\n        //\n        // 修法：用 putIfAbsent 的返回值区分身份 —— null = **我是拥有者**（负责抓，绝不等）；\n        // 非 null = 已有同名请求在飞（**才等**，等到了复用它的缓存，等不到自己兜底抓一次）。\n        val mine = java.util.concurrent.CountDownLatch(1)\n        val inflight = boardPageGate.putIfAbsent(v.url, mine)\n        if (inflight != null) {\n            runCatching { inflight.await(8, java.util.concurrent.TimeUnit.SECONDS) }\n            boardPageFresh(v.url)?.let { return it }\n        }\n        try {\n            // ★ 第 83 轮提速（用户报「三次元板块点开封面到介绍页要 20 秒」；\n            //   三次元 = 除 han1me 官方站与优选之外的所有板块）：\n            //\n            // 原来这里两个分支**各自去抓同一个页面**：boardDetail 失败/超时后，\n            // metaDetail 再完整抓一遍，每次又各自带重试 —— 同页最多抓 4 次。\n            //\n            // 修法：**共享一份正文缓存**（getHtmlCached，60 秒 TTL）：\n            //  · 先照旧试 boardDetail（原生板块能命中就还是一抓即得，**不预抓、不倒退**）；\n            //  · 它失败/不适用时，用缓存抓一次正文交给 metaDetailOf 解析，\n            //    若这份正文已经因上面的 `getHtmlCached` 命中缓存，就连这一次网络都省了。\n            val native = if (isNativeBoardUrl(v.url)) runCatching { boardDetail(v) }.getOrNull() else null\n            val d = native ?: runCatching {\n                val h = getHtmlCached(v.url) ?: return@runCatching null\n                metaDetailOf(v, h)\n            }.getOrNull()\n            if (d != null) boardPageRemember(v.url, d)\n            return d\n        } finally {\n            // ★ 只有**拥有者**摘表放行；等待者不能动别人放进来的表项（否则互相摘除）。\n            if (inflight == null) boardPageGate.remove(v.url)?.countDown()\n        }\n    }\n'),
