                '    /**\n     * **321av 原生直链**（第 124 轮，设备侧逐步验证打通）：\n     *   ① 详情页 /vodplay/<id>-1-1.html 里有 var player_aaaa={...}；\n     *   ② encrypt=1 走 URLDecode，encrypt=2 走 base64 再 URLDecode；\n     *   ③ 解出 {"ss":[[0,"/cn/k1382"]]}，末段是**集码**；\n     *   ④ GET /private-getvideo/<集码> 回 JSON，其中 url 就是真 m3u8\n     *      （实测 21283 B / 665 分片，一次就通）。\n     * 之前只能网页播放，是因为页面 HTML 里**根本没有 m3u8 字符串**。\n     */\n    fun av321Detail(v: HanimeVideo): HanimeDetail? {\n        val html = getHtml(v.url, referer = originOf(v.url) + "/")\n        val mx = Regex("""var\\s+player_aaaa\\s*=\\s*(\\{[^<]*)""").find(html)\n        val raw = mx?.groupValues?.get(1)?.trim() ?: return null\n        val obj = runCatching { org.json.JSONObject(raw) }.getOrNull() ?: return null\n        val enc = obj.optString("encrypt", "0")\n        var u = obj.optString("url", "")\n        if (u.isBlank()) return null\n        // ★★★ 第 125 轮（用户报「321av 没生效」）：**解码顺序修对**。\n        //\n        // 实测（设备侧 r444/r445）：encrypt=1 的 url 形如\n        //   %65%79%4A%7A%63%79%49%36%57%31%73%77...\n        // 解码链是 **URLDecode -> base64 -> JSON**，两步都要走：\n        //   URLDecode  -> eyJzcyI6W1swLCIvY24vazEzODIiXV19\n        //   base64     -> {"ss":[[0,"/cn/k1382"]]}\n        // 上一版 encrypt=1 只做 URLDecode，得到的是 base64 串，\n        // 里面**没有 /cn/** -> 正则匹配不到 -> return null -> 落回网页播放。\n        //\n        // 现在统一按「先 URLDecode、再 base64（失败就保留）」处理，两种 encrypt 都覆盖。\n        u = runCatching { java.net.URLDecoder.decode(u, "UTF-8") }.getOrDefault(u)\n        if (u.contains("eyJ") || !u.contains("{")) {\n            u = runCatching { String(java.util.Base64.getDecoder().decode(u), Charsets.UTF_8) }.getOrDefault(u)\n        }\n        val code = Regex("""/cn/([A-Za-z0-9_-]{2,})""").find(u)?.groupValues?.get(1)\n            ?: return null\n        val api = originOf(v.url) + "/private-getvideo/" + code\n        val js = getHtml(api, referer = v.url)\n        if (js.isBlank()) return null\n        val master = Regex(""""url"\\s*:\\s*"(https?://[^"]+?\\.m3u8[^"]*)"""").find(js)?.groupValues?.get(1)\n            ?: return null\n        val list = getPlaylist(master, v.url)\n        if (list.isEmpty()) return null\n        val sources = renditionsOf(master, list)\n        if (sources.isEmpty()) return null\n        openNativeDetail(v.url, listOf(master) + sources.map { it.second })\n        val title = unescape(ogTitleRe.find(html)?.groupValues?.get(1).orEmpty()).ifBlank { v.title }\n        return HanimeDetail(\n            video = v.copy(title = title, thumb = ogImageRe.find(html)?.groupValues?.get(1).orEmpty().ifBlank { v.thumb }),\n            description = "", tags = emptyList(), sources = sources, related = emptyList(),\n            isFav = false, isSaved = false, saveListId = "",\n        )\n    }\n\n    fun streamVarDetail(v: HanimeVideo): HanimeDetail? {',
