                '    // ==================== 第 129 轮：新增三个原生板块（免 DoH 快速站） ====================\n    //\n    // 来源：用户提供的《视频站清单_免DoH_快速》第 1/2/4 名。\n    // 三站实测（2026-10-28，设备侧 curl）：\n    //   ① 5x5x影院  —— /vd/<id>/ 纯 SSR，详情页**直出 m3u8 与 mp4**（最好做的一类）\n    //   ② Lvmao影院 —— 与 5x5x **同一套模板**（页面结构逐字相同，只有品牌不同），共用解析器\n    //   ③ 中国x站   —— 结构不同，单独处理\n    //\n    // 线路策略（用户截图给了发布页与 3 条最新地址，本机实测只有部分可用）：\n    //   5x5x  : yxv7985.vip ✅ / wpiemmt.vip ✅ / kq9119w.vip ❌ / dczvysq.vip ❌\n    //   Lvmao : snfa25.vip ✅ / f9pofc.vip ✅ / khioj6.vip ❌ / m0jlbnt.vip ❌\n    // 所以每个站配**多条线路**，由既有 selectedLine 机制选中的那条来用（用户可手动切）。\n\n    const val SITE5_NAME = "5x5x影院"\n    const val SITE5_HOME = "https://www.yxv7985.vip"\n    const val SITE5_ALT1 = "https://www.wpiemmt.vip"\n\n    const val LVMAO_NAME = "Lvmao影院"\n    const val LVMAO_HOME = "https://www.snfa25.vip"\n    const val LVMAO_ALT1 = "https://www.f9pofc.vip"\n\n    const val CNX_NAME = "中国x站"\n    const val CNX_HOME = "https://4399acg.com"\n\n    // 第 142 轮（真机日志：www.svt75lf.vip / www.wpiemmt.vip 连续 0/3 失败、卡 19.9 秒）：\n// 站群域名每天换，写死的候选会不断失效。按实测存活率重排：\n//   w2torc / yx11ni / 9b1mxq = 3/3 成功；ggasn09 = 1/3；svt75lf / wpiemmt = 0/3（已移除）。\n// 注意：**识别不依赖这份名单**（isSite5Url 走路径+指纹），这里只影响线路候选的优先顺序。\nprivate val site5Roots = setOf(\n    "w2torc.vip", "yx11ni.vip", "9b1mxq.vip",\n    "ggasn09.vip", "yxv7985.vip",\n    "kq9119w.vip", "dczvysq.vip", "55tnbkbt.vip",\n)\n    private val lvmaoRoots = setOf("snfa25.vip", "f9pofc.vip", "khioj6.vip", "m0jlbnt.vip", "l869flez.vip")\n\n    /** 5x5x 家族（含 Lvmao，同模板）：/vd/<数字>/ 作品页。 */\n    /**\n     * 5x5x 作品页判定（第 141 轮重写）。\n     * 旧实现靠写死的域名白名单，而这是每天换域名的站群，白名单过期就再也认不出，\n     * 于是 site5Detail 永不被调用、直链消失。\n     * 改为按路径 + 站点指纹识别，不依赖域名。\n     */\n    fun isSite5Url(u: String): Boolean = isSite5LikeUrl(u)\n\n    private val site5DetailPathRe = Regex("""^/vd/[0-9]+/?$""")\n\n    private fun isSite5LikeUrl(u: String): Boolean {\n        if (!site5DetailPathRe.matches(pathOnly(u))) return false\n        val h = runCatching { URI(u).host.orEmpty().lowercase() }.getOrDefault("")\n        if (site5Roots.any { h.endsWith(it) }) return true\n        return site5Fingerprint(u)\n    }\n\n    @Volatile private var site5FpAt: Long = 0L\n    @Volatile private var site5FpHost: String = ""\n    @Volatile private var site5FpOk: Boolean = false\n\n    private fun site5Fingerprint(u: String): Boolean {\n        val h = runCatching { URI(u).host.orEmpty().lowercase() }.getOrDefault("")\n        if (h.isBlank()) return false\n        val now = System.currentTimeMillis()\n        if (h == site5FpHost && now - site5FpAt < 30 * 60_000L) return site5FpOk\n        val html = runCatching { getHtml(u, referer = originOf(u) + "/") }.getOrDefault("")\n        val ok = html.contains("ttikkhdgtgsjuy.com") || html.contains("xiahduashujkh966.com")\n        site5FpHost = h; site5FpAt = now; site5FpOk = ok\n        return ok\n    }\n\n    /** Lvmao 与 5x5x 同模板同 CDN，判定逻辑一致。 */\n    fun isLvmaoUrl(u: String): Boolean {\n        if (!site5DetailPathRe.matches(pathOnly(u))) return false\n        val h = runCatching { URI(u).host.orEmpty().lowercase() }.getOrDefault("")\n        if (lvmaoRoots.any { h.endsWith(it) }) return true\n        return site5Fingerprint(u)\n    }\n\n    fun isCnxUrl(u: String): Boolean {\n        val h = runCatching { URI(u).host.orEmpty().lowercase() }.getOrDefault("")\n        // 第 139 轮（真机日志定位）：原判据 startsWith("/v/") 永远不成立 ——\n        // 中国x站作品页真实路径是 /video/<id>.html（实测 /video/1210835863.html），\n        // 而 /video/ 并不以 /v/ 开头，于是 isCnxUrl 恒 false、boardOf 不认 cnx、\n        // cnxDetail 从来没被调用过 —— 这就是该站永远拿不到直链的真因。\n        // 现在同时接受 /video/ 与 /v/（后者是早期形态，保留兼容）。\n        val p = pathOnly(u)\n        return h.contains("4399acg") &&\n            (p.startsWith("/video/") || p.startsWith("/v/"))\n    }\n\n    /**\n     * 5x5x / Lvmao 家族详情（第 129 轮）。\n     *\n     * 实测（2026-10-28）：详情页 HTML 里**直出**两条媒体地址：\n     *   m3u8 -> https://ttikkhdgtgsjuy.com:1443/v/<hash>/index.m3u8\n     *   mp4  -> https://xiahduashujkh966.com/assets/<hash>.mp4\n     * 不需要任何解码/派发口 —— 直接取，一次往返就完事。\n     */\n    fun site5Detail(v: HanimeVideo): HanimeDetail? {\n        val html = getHtml(v.url, referer = originOf(v.url) + "/")\n        // 实测（2026-10-28）详情页把播址放在无引号属性里：\n        //   data-m3u8=https://.../index.m3u8   data-mp4=<相对名>.mp4   data-dl-base=https://.../assets/\n        // 还有一条 <a href=https://.../xxx.mp4 class=action-btn download> 是完整直链。\n        val m3u8 = Regex("""(https?://[^\'"\\s]*\\.m3u8[^\'"\\s]*)""").find(html)?.groupValues?.get(1)\n        val mp4abs = Regex("""href=(https?://[^\'" >]*\\.mp4)[^ >]*class=action-btn""").find(html)?.groupValues?.get(1)\n            ?: Regex("""href=(https?://[^\'" >]*\\.mp4)""").find(html)?.groupValues?.get(1)\n        if (m3u8 == null && mp4abs == null) return null\n        val sources = ArrayList<Pair<Int, String>>()\n        // ★★★ 第 132 轮（用户要求「下载速度最大化，保守稳定提升」）：**mp4 直链优先于 m3u8 分片**。\n        //\n        // 真机实测（2026-10-28，设备侧 curl，同一部片子）：\n        //   · m3u8 分片  ：45~55 KB/s（单分片 87 KB 要 1.6~1.9 秒）—— 该 CDN 对每个小分片都要新建连接，\n        //                  服务端限速明显；479 片的小文件就是「一片一片慢慢下」。\n        //   · mp4 直链  ：**1.25~1.69 MB/s**（5 MB range 请求 3.1~4.2 秒），**快 25~37 倍**。\n        //\n        // 所以该站家族**优先用 mp4**：全量单文件、单连接、可断点续传。\n        // 保守处：m3u8 仍作为第二选择保留（mp4 不可达时自动回落），不删除任何既有能力。\n        if (mp4abs != null) sources.add(720 to mp4abs)\n        if (m3u8 != null) {\n            val list = getPlaylist(m3u8, v.url)\n            if (list.isNotEmpty()) sources.addAll(renditionsOf(m3u8, list))\n        }\n        if (sources.isEmpty() && m3u8 != null) sources.add(qualityFromUrl(m3u8) to m3u8)\n        if (sources.isEmpty()) return null\n        openNativeDetail(v.url, sources.map { it.second })\n        return htmlDetail(v, html, sources)\n    }\n    fun cnxListing(base: String, page: Int): List<HanimeVideo> {\n        val origin = originOf(base)\n        val cat = cnxCategory(origin) ?: return emptyList()\n        val u = origin + "/list/" + cat + "-" + page + ".html"\n        return parseGeneric(u, decodeJsWrite(getHtml(u, referer = origin + "/")))\n    }\n\n    @Volatile private var cnxCatAt: Long = 0L\n    @Volatile private var cnxCatId: String = ""\n\n    /** 取首页第一个分类 id（/list/<id>-1.html），缓存 6 小时。 */\n    private fun cnxCategory(origin: String): String? {\n        val now = System.currentTimeMillis()\n        if (cnxCatId.isNotEmpty() && now - cnxCatAt < 6 * 3600_000L) return cnxCatId\n        val home = decodeJsWrite(runCatching { getHtml(origin + "/", referer = origin + "/") }.getOrDefault(""))\n        val id = Regex("""/list/([0-9]+)-1\\.html""").find(home)?.groupValues?.get(1) ?: return null\n        cnxCatId = id; cnxCatAt = now\n        return id\n    }\n\n    /**\n     * 中国x站详情：**播址由页面内联 JS 给出，HTML 里没有 m3u8 字符串**。\n     * 实测页面有 playFilteredHLS(<video>, <https://m.892539.xyz/play.php?site_id=..&source_id=..>, <key>)，\n     * 该接口**直接返回真 m3u8**（实测 167644 B 等，含 AES-128 密钥）。\n     * m3u8 取不到时回落页面里的 mp4 直链，不直接判死。\n     */\n    /** 中国x站的可用「源」编号（第 135 轮实测：12 / 13 / 27 / 28 均曾出清单；26/29~32 为空）。 */\n    private val CNX_SITE_IDS = listOf(28, 13, 12)\n\n    /**\n     * 多源尝试的**总时间预算**（毫秒）。\n     * 实测该接口在部分网络（如手机移动网络）下**无论请求头怎么配都返回 200 + 0 字节**，\n     * 没有预算的话 3 个源会各等一次超时 -> 详情页白白多等十几秒。\n     * 超预算就停手、如实回落网页播放（不假装成功）。\n     */\n    private const val CNX_SRC_BUDGET_MS = 12_000L\n\n    /**\n     * 从一份 m3u8 里取出**分片所在的 CDN 域名**（第 145 轮）。\n     *\n     * 用途：中国x站的多个 site_id 会返回**分片 CDN 不同**的清单，\n     * 用它把「同一家 CDN」的线路去重，只保留真正不同的几家（见 cnxDetail）。\n     */\n    private fun cnxSegHost(list: String): String {\n        val seg = list.lineSequence()\n            .firstOrNull { it.isNotBlank() && !it.startsWith("#") }\n            .orEmpty().trim()\n        if (seg.isEmpty()) return ""\n        return runCatching { URI(seg).host.orEmpty() }.getOrDefault(seg.take(30))\n    }\n\n    fun cnxDetail(v: HanimeVideo): HanimeDetail? {\n        val html = decodeJsWrite(getHtml(v.url, referer = originOf(v.url) + "/"))\n        var master = Regex("""(https?://[^"\'\\s]*\\.m3u8[^"\'\\s]*)""").find(html)?.groupValues?.get(1)\n        val mp4 = Regex("""(https?://[^"\'\\s]*\\.mp4[^"\'\\s]*)""").find(html)?.groupValues?.get(1)\n        if (master == null) {\n            val api = Regex("""playFilteredHLS\\(.[^,]+,\\s*\'(https?://[^\']+)\'""").find(html)?.groupValues?.get(1)\n            // ★★★ 第 135 轮（用户用浏览器嗅探给出 site_id=28 的可用直链，循此找到突破口）：\n            //\n            // 实测（2026-10-28）**同一个 source_id 在不用 site_id 下都能出清单，但长度/可用性不同**：\n            //   source 167096: site12=29433  site13=62910  site27=100763  site28=206813\n            //   source 59933 : site12=167644 site13=30797  site27=**0**   site28=22741\n            // 也就是说：**site_id 是「线路/源」，source_id 是「片子」**，\n            // 某片在 A 源没数据、在 B 源有 —— 这正是之前「全部 0 字节」的真因（详情页只会给其中一个源）。\n            //\n            // 所以不再只信详情页那一个：**依次试多个源，第一个能出清单的就用**。\n            // 详情页给的源排在最前（保持站点本意），其余按实测可用性顺序兜底。\n            if (api != null) {\n                val candidates = LinkedHashSet<String>()\n                candidates.add(api)\n                for (sid in CNX_SITE_IDS) {\n                    candidates.add(Regex("""site_id=[0-9]+""").replace(api, "site_id=" + sid))\n                }\n                val t0 = System.currentTimeMillis()\n                // ★★★ 第 145 轮（真机：移动流量下**中国x站播放有问题**，而 5x5x/Lvmao 正常）：\n                //\n                // 根因是「只取第一条能出清单的线路」。实测同一个 source_id 在不同 site_id 下\n                // **分片 CDN 完全不同**（2026-10-30，PC 侧逐源验证）：\n                //   site12 -> v8.lj20250710new.com  （252 段）\n                //   site13 -> v2025.ddcdnbf.com     （4737 段）\n                //   site27 -> lsbbf5.com            （5396 段）\n                // 三家 CDN 分属不同服务商，**运营商对它们的可达性并不一致** ——\n                // 只押第一条，撞上不可达的那家就整片播不了（这正是用户报的现象）。\n                //\n                // 所以改为：把**分片 CDN 不同**的源都收进来当多线路，交给播放器；\n                // 播放器里可切换，也便于它自己容错。最多 3 条，仍在原有时间预算内。\n                val lines = ArrayList<Pair<Int, String>>()\n                val byHost = HashSet<String>()\n                for (cand in candidates) {\n                    if (System.currentTimeMillis() - t0 > CNX_SRC_BUDGET_MS) break\n                    val list = getPlaylist(cand, v.url)\n                    if (list.isEmpty()) continue\n                    val s = renditionsOf(cand, list)\n                    if (s.isEmpty()) continue\n                    val host = cnxSegHost(list)\n                    if (!byHost.add(host)) continue\n                    // 同一画质号在多条线路上会互相覆盖，按线路序号错开末位（720 -> 720/721/722）。\n                    val off = byHost.size - 1\n                    s.forEach { (q, u) -> lines.add((q - q % 10 + off) to u) }\n                    if (byHost.size >= 3) break\n                }\n                if (lines.isNotEmpty()) {\n                    openNativeDetail(v.url, lines.map { it.second })\n                    return htmlDetail(v, html, lines)\n                }\n                master = api\n            }\n        }\n        val sources = ArrayList<Pair<Int, String>>()\n        if (master != null) {\n            val list = getPlaylist(master, v.url)\n            if (list.isNotEmpty()) sources.addAll(renditionsOf(master, list))\n            if (sources.isEmpty()) sources.add(qualityFromUrl(master) to master)\n        }\n        if (sources.isEmpty() && mp4 != null) sources.add(720 to mp4)\n        if (sources.isEmpty()) return null\n        openNativeDetail(v.url, sources.map { it.second })\n        return htmlDetail(v, html, sources)\n    }\n\n    /**\n     * 5x5x / Lvmao 列表（第 133 轮修分页）。真机实测：首页没有分页器，/page/2/ 回的是同一页\n     * （55 卡 100% 重叠）—— 这就是「只有一页可以看」。真正可翻页的是分类页 /category/<id>/，\n     * 页内有「第 1 / 544 页」与下一页按钮，形式 /category/<id>/page/<n>/（实测第 2 页 23 卡、零重叠）。\n     */\n    fun site5Listing(base: String, page: Int): List<HanimeVideo> {\n        val origin = originOf(base)\n        val cat = site5Category(origin)\n        val u = if (page <= 1) origin + "/category/" + cat + "/"\n            else origin + "/category/" + cat + "/page/" + page + "/"\n        return parseGeneric(u, getHtml(u, referer = origin + "/"))\n    }\n\n    @Volatile private var site5CatAt: Long = 0L\n    @Volatile private var site5CatId: String = ""\n\n    /** 首个分类 id（从首页 /category/<id>/ 取），缓存 6 小时。 */\n    private fun site5Category(origin: String): String {\n        val now = System.currentTimeMillis()\n        if (site5CatId.isNotEmpty() && now - site5CatAt < 6 * 3600_000L) return site5CatId\n        val home = runCatching { getHtml(origin + "/", referer = origin + "/") }.getOrDefault("")\n        val id = Regex("""/category/([0-9]+)/""").find(home)?.groupValues?.get(1)\n        if (id != null) { site5CatId = id; site5CatAt = now }\n        return id ?: "1"\n    }\n\n    /**\n     * **5x5x / Lvmao 搜索**：实测这两站的搜索是 **JS 客户端渲染**，HTML 里没有卡片；\n     * 真正的数据接口是 /api/search/video?keyword=<关键词>&page=<页>。\n     * 返回 JSON：data.list[{id,litpic,title,tags,typename}] + total_pages。\n     * 所以搜索必须走 JSON，不能像列表页那样 parseGeneric（搜索页 0 个 /vd/ 链接）。\n     */\n    fun site5Search(base: String, kw: String, page: Int): List<HanimeVideo>? {\n        val origin = originOf(base)\n        val u = origin + "/api/search/video?keyword=" + URLEncoder.encode(kw, "UTF-8") + "&page=" + page\n        val js = runCatching { getHtml(u, referer = origin + "/") }.getOrDefault("")\n        if (js.isBlank()) return null\n        val arr = runCatching {\n            org.json.JSONObject(js).optJSONObject("data")?.optJSONArray("list")\n        }.getOrNull() ?: return null\n        val out = ArrayList<HanimeVideo>()\n        for (i in 0 until arr.length()) {\n            val ob = arr.optJSONObject(i) ?: continue\n            val id = ob.optString("id")\n            if (id.isBlank()) continue\n            out.add(HanimeVideo(\n                id = id,\n                url = origin + "/vd/" + id + "/",\n                title = ob.optString("title"),\n                thumb = ob.optString("litpic"),\n                duration = "", likes = "", views = "", brand = "",\n            ))\n        }\n        return out\n    }\n\n    /**\n     * **中国x站搜索**：实测 /search.php?content=<关键词> 会 302 到 /list/<合成id>-1.html，\n     * 跟随重定向后就是标准列表页（20 卡/页）。getHtml 默认跟随重定向，直接解析即可。\n     */\n    fun cnxSearch(base: String, kw: String): List<HanimeVideo>? {\n        val origin = originOf(base)\n        val u = origin + "/search.php?content=" + URLEncoder.encode(kw, "UTF-8")\n        val html = decodeJsWrite(runCatching { getHtml(u, referer = origin + "/") }.getOrDefault(""))\n        if (html.isBlank()) return null\n        return parseGeneric(u, html)\n    }\n    fun isOkxxxUrl(u: String): Boolean',
