                '    // ==================== 第 205 轮：KT-play 族 302 跟随（99热 / 青青草）====================\n    //\n    // 用户提供的真实直链 + 设备实测：\n    //\n    //  99热：  https://www.99jj28.com/get_file/3/<hash>/135000/135755/135755.mp4/?rnd=…\n    //          ->302-> https://media-vip-s.99rego.com/remote_control.php?time=&cv=&file=…\n    //          跟随 + Range 0-1023 => **206 / 1024B / video/mp4**（真视频）\n    //\n    //  青青草：https://qyul34.com/get_file/3/<hash>/181000/181105/181105.mp4/?br=586&rnd=…\n    //          ->302-> https://qd.qdddhd.com/remote_control.php?time=&cv=&file=…\n    //          跟随 + Range => **206 / 1024B / video/mp4**（真视频）\n    //\n    // 两者都是同一套 KT-play 模板：get_file 只做 302 派发，**必须自己跟到 remote_control.php**。\n    // 而 ExoPlayer 无法完成这个带签名的跳转（签名与时间戳绑定），所以旧实现交给播放器就播不了。\n    //\n    // 修法：抽一个通用的 follow302()，在返回 HanimeDetail 之前把地址跟到最终形态。\n    private fun follow302(u0: String, referer: String): String {\n        var cur = u0\n        var hop = 0\n        while (hop < 3) {\n            val next = runCatching {\n                val req = okhttp3.Request.Builder().url(cur)\n                    .header("User-Agent", UA)\n                    .header("Referer", referer)\n                    .build()\n                noRedirectHttp.newCall(req).execute().use { r ->\n                    if (r.code in 300..399) {\n                        // 第 206 轮（真机实测该站返回**小写 location**）\n                        r.header("Location") ?: r.headers.firstOrNull { h -> h.first.equals("location", true) }?.second\n                    } else null\n                }\n            }.getOrNull()\n            if (next.isNullOrBlank()) break\n            cur = if (next.startsWith("http")) next else originOf(cur) + next\n            hop++\n        }\n        return cur\n    }\n\n    fun isEmbedPlayerUrl(u: String): Boolean {',
