            ('    val shown = if (favFilter == "全部") local else local.filter { it.board == favFilter }\n', '    val shown = if (favFilter == "全部") local else local.filter { it.board == favFilter }\n    // 第 59 轮：**预取**（用户反馈「收藏页点进介绍页太慢」）。\n    // 这一屏可见项的详情先在后台取回来；用户真点的时候命中缓存直接秒开。\n    // 只写缓存、不返回给界面（界面仍走 boardPage，逻辑单一）；失败静默。\n    androidx.compose.runtime.LaunchedEffect(favTick, favFilter) {\n        val vs = shown.take(3).map { it2 ->\n            HanimeVideo(\n                id = it2.url, url = it2.url, title = it2.title, thumb = it2.thumb,\n                duration = "", likes = "", views = "", brand = it2.board,\n            )\n        }\n        runCatching { X99.prefetchBoardPage(vs) }\n    }\n'),
            ('        // 每次打开程序：先为 hanime 官方源筛选最快的「内置 Hosts 边缘节点」，再加载首页\n        // （走代理时域名由代理解析，节点不参与——跳过测速省时间）\n        scope.launch {\n            val picked: Map<String, Long> = kotlinx.coroutines.withContext(Dispatchers.IO) {\n                runCatching {\n                    if (HanimeClient.edgeHostsEnabled && !HanimeClient.proxyInUse()) HanimeClient.pickFastestNode()\n                    else emptyMap()\n                }.getOrDefault(emptyMap())\n            }\n            val n = HanimeClient.edgeNode\n            if (picked.isNotEmpty() && n.isNotBlank() && (picked[n] ?: -1L) >= 0) {\n                toast = "边缘节点已选最快：$n（${picked[n]} ms）"\n            }\n            loadHome()\n        }\n', '        // 每次打开程序：**后台**为 hanime 官方源筛选最快的内置 Hosts 边缘节点（不挡首页）。\n        // （走代理时域名由代理解析，节点不参与——跳过测速省时间）\n        scope.launch {\n            val picked: Map<String, Long> = kotlinx.coroutines.withContext(Dispatchers.IO) {\n                runCatching {\n                    if (HanimeClient.edgeHostsEnabled && !HanimeClient.proxyInUse()) HanimeClient.pickFastestNode()\n                    else emptyMap()\n                }.getOrDefault(emptyMap())\n            }\n            val n = HanimeClient.edgeNode\n            if (picked.isNotEmpty() && n.isNotBlank() && (picked[n] ?: -1L) >= 0) {\n                toast = "边缘节点已选最快：$n（${picked[n]} ms）"\n            }\n        }\n        // 首页**立即**加载（不等上面那条测速协程）。\n        scope.launch { loadHome() }\n'),
            # 70g. ★ 板块源区块挂在**真正的设置面板**（settingsOpen 展开处；MinePanel 不是那个界面）
            ('            if (settingsOpen) {\n                Spacer(Modifier.height(6.dp))\n                NetSettingsSection()\n            }', '            if (settingsOpen) {\n                Spacer(Modifier.height(6.dp))\n                // 第 70 轮：板块源切换 + 连通性检测（用户要求「在设置页面新建一个板块源切换选项」）。\n                // 挂在**展开后的设置区**里（与网络设置同层），用户点「设置」即可看到。\n                CatalogSourceSection()\n                Spacer(Modifier.height(10.dp))\n                NetSettingsSection()\n            }'),
            # 70h. 板块源区块本体（检测连通性 + 手动切换，不自动）
            ('/** 网络设置：全应用走代理 + 播放中继 + DoH + 代理模式（自动/直连/手动）+ 状态与重新探测。 */', '/**\n * 「板块源」设置区块（第 70 轮，用户要求）。\n *\n * 用户原话：「在设置页面新建一个板块源切换选项，并对主板块源和这两个备用的连通性进行检测，\n *           手动切换不自动」。\n *\n * 三个源（x99dh.cc / .vip / .my）实测返回**同一份目录**，但可用性会各自波动，所以：\n *  · 点「检测连通性」并发探测三者，显示**耗时 + 解出的站点数**；\n *  · 用户点某一条即切换（**绝不自动切**）；\n *  · 判据是「能解出目录」，不是 HTTP 码 —— 实测三者都回 500 但正文正常。\n */\n@Composable\nprivate fun CatalogSourceSection() {\n    var current by remember { mutableStateOf(X99.catalogSource()) }\n    var expanded by remember { mutableStateOf(false) }\n    var probes by remember { mutableStateOf<Map<String, X99.SourceProbe>>(emptyMap()) }\n    var busy by remember { mutableStateOf(false) }\n    val scope = rememberCoroutineScope()\n\n    Text(\n        "🗂 板块源 " + (if (expanded) "▾" else "▸"),\n        color = Color.White, fontSize = 14.sp, fontWeight = FontWeight.SemiBold,\n        modifier = Modifier.fillMaxWidth().clickable { expanded = !expanded }.padding(vertical = 4.dp),\n    )\n    if (!expanded) return\n\n    Text(\n        "板块列表（站点目录）从这里取。三个源内容相同，哪个通用哪个；**手动切换，不会自动跳**。",\n        color = TextFaint, fontSize = 10.5.sp, lineHeight = 15.sp,\n    )\n    Spacer(Modifier.height(6.dp))\n\n    X99.CATALOG_SOURCES.forEach { src ->\n        val p = probes[src]\n        val active = src == current\n        Row(\n            verticalAlignment = Alignment.CenterVertically,\n            modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp),\n        ) {\n            Text(\n                (if (active) "● " else "○ ") + src,\n                color = if (active) Color.White else Color(0xFFCFCFD4), fontSize = 12.sp,\n                modifier = Modifier.weight(1f),\n            )\n            // 检测结果：耗时 + 站点数（-1 = 不通）\n            Text(\n                when {\n                    p == null -> "未检测"\n                    p.ms < 0 -> "不通"\n                    p.sites <= 0 -> "通了但无目录"\n                    else -> "${p.ms} ms · ${p.sites} 站"\n                },\n                color = when {\n                    p == null -> TextFaint\n                    p.ok -> Color(0xFF7BD88F)\n                    else -> Color(0xFFFF8A8A)\n                },\n                fontSize = 11.sp,\n            )\n            Spacer(Modifier.width(8.dp))\n            TextButton(\n                onClick = {\n                    X99.setCatalogSource(src)\n                    current = src\n                },\n            ) {\n                Text(if (active) "当前" else "切换", color = if (active) TextFaint else AccentRed, fontSize = 11.sp)\n            }\n        }\n    }\n    Spacer(Modifier.height(4.dp))\n    Row(verticalAlignment = Alignment.CenterVertically) {\n        TextButton(onClick = {\n            if (busy) return@TextButton\n            busy = true\n            scope.launch {\n                val rr = kotlinx.coroutines.withContext(Dispatchers.IO) { X99.probeAllCatalogSources() }\n                probes = rr.associateBy { it.url }\n                busy = false\n            }\n        }) { Text(if (busy) "检测中…" else "检测连通性", color = AccentRed, fontSize = 12.sp) }\n        Spacer(Modifier.width(6.dp))\n        Text(\n            if (probes.isEmpty()) "点右侧按钮并发检测三个源的可用性与耗时"\n            else "检测完成；切换后下次进板块即生效（已缓存会自动重取）",\n            color = TextFaint, fontSize = 10.5.sp,\n        )\n    }\n    Spacer(Modifier.height(4.dp))\n}\n\n/** 网络设置：全应用走代理 + 播放中继 + DoH + 代理模式（自动/直连/手动）+ 状态与重新探测。 */'),
            # 70j. 板块源文案去掉 Markdown 星号（Compose Text 不解析，会原样露出）
            ('        "板块列表（站点目录）从这里取。三个源内容相同，哪个通用哪个；**手动切换，不会自动跳**。",\n        color = TextFaint, fontSize = 10.5.sp, lineHeight = 15.sp,', '        // 注意：Compose 的 Text 不解析 Markdown，星号会原样显示出来（实测截图里就露出来了），\n        // 所以这里用纯文本措辞，不用 ** 强调。\n        "板块列表（站点目录）从这里取。三个源内容相同，哪个通用哪个；手动切换，不会自动跳。",\n        color = TextFaint, fontSize = 10.5.sp, lineHeight = 15.sp,'),
            # 70k. 修正按钮方位描述（按钮在左，原文说“右侧”）
            ('        Text(\n            if (probes.isEmpty()) "点右侧按钮并发检测三个源的可用性与耗时"\n            else "检测完成；切换后下次进板块即生效（已缓存会自动重取）",\n            color = TextFaint, fontSize = 10.5.sp,\n        )', '        Text(\n            if (probes.isEmpty()) "点左侧「检测连通性」并发检测三个源的可用性与耗时"\n            else "检测完成；切换后下次进板块即生效（已缓存会自动重取）",\n            color = TextFaint, fontSize = 10.5.sp,\n        )'),
            # 71g. ★ 设置页挂上「备份/恢复」区块（用户要求换新设备无缝衔接）
            ('                CatalogSourceSection()\n                Spacer(Modifier.height(10.dp))\n                NetSettingsSection()\n            }', '                CatalogSourceSection()\n                Spacer(Modifier.height(10.dp))\n                NetSettingsSection()\n                Spacer(Modifier.height(10.dp))\n                // 第 71 轮：备份/恢复（用户要求「换新设备无缝衔接」，含收藏与云端登录数据、不含已下载）。\n                com.han1me.backup.BackupRestoreSection()\n            }'),
            # 71h. ★ localFileDetail 读 sidecar：直链用原始 url（用户要的直链）、介绍页有封面/简介、收藏可还原
            ('private fun localFileDetail(path: String): HanimeDetail {\n    val f = java.io.File(java.io.File(path).parentFile, "")\n    val name = f.name.ifBlank { "本机媒体" }\n    return HanimeDetail(\n        video = HanimeVideo(\n            id = "local:" + java.net.URI(path).path.orEmpty().hashCode(),\n            url = "https://local-file.invalid/" + name.trimEnd(\'/\'),\n            title = name,\n            thumb = "",\n            duration = "",\n            likes = "",\n            views = "",\n            brand = "本机",\n        ),\n        description = "这是已下载到本机的副本，断网也能播。",\n        tags = listOf("本机"),\n        sources = listOf(0 to "file://" + path),\n        related = emptyList(),\n        isFav = false,\n        isSaved = false,\n        saveListId = "",\n    )\n}', 'private fun localFileDetail(path: String): HanimeDetail {\n    // 第 71 轮（用户报的 3 个 bug 的**共同根因**）：本机条目的详情原来只从**文件名**拼出来，\n    // sidecar（`*.detail.json`）里明明存着原始信息却没用上，于是：\n    //  ① 「复制直链」拿到的是 `file:///…`（用户要的是**原始在线直链**）；\n    //  ② 介绍页没有封面/简介/标签；\n    //  ③ 收藏页无法还原成「可打开的介绍页」。\n    // 现在**优先读 sidecar**：拿到原始 url / 标题 / 封面 / 源清单 / 板块，只把播放地址换成本机文件。\n    val side = com.han1me.download.HplayDownloads.readSidecarFor(path)\n    val f = java.io.File(java.io.File(path).parentFile, "")\n    val name = side?.title?.ifBlank { null } ?: f.name.ifBlank { "本机媒体" }\n    // 播放源：**本机文件**（离线可播）。这是唯一的替换点 —— 其余字段都用 sidecar 的真值。\n    val localPlay = "file://" + java.net.URLEncoder.encode(path, "UTF-8")\n        .replace("+", "%20").replace("%2F", "/").replace("%3A", ":")\n    return HanimeDetail(\n        video = HanimeVideo(\n            // id 用 sidecar 的原始 url 最稳（收藏/查重都以它为准）；没有才退回路径哈希\n            id = side?.url?.ifBlank { null } ?: ("local:" + java.net.URI(path).path.orEmpty().hashCode()),\n            // ★ 用户要的「打开就是视频直链」：url 用**原始在线直链**，不是 file://\n            url = side?.url?.ifBlank { null } ?: ("https://local-file.invalid/" + name.trimEnd(\'/\')),\n            title = name,\n            thumb = side?.cover.orEmpty(),\n            duration = side?.duration.orEmpty(),\n            likes = "",\n            views = "",\n            brand = side?.brand?.ifBlank { null } ?: "本机",\n        ),\n        // 介绍页：优先用 sidecar 的简介/标签；再标注这是本机离线副本\n        description = (side?.description.orEmpty().ifBlank { "这是已下载到本机的副本，断网也能播。" }) +\n            "\\n\\n（本机离线副本：介绍页与封面已随下载一并缓存）",\n        tags = (side?.tags.orEmpty().ifEmpty { listOf("本机") }) + listOf("本机"),\n        // 源清单：**本机文件排第一**（点播放即播本地），后面附 sidecar 里的在线源\n        sources = listOf(0 to localPlay) + side?.sources.orEmpty().map { (q, u) -> q to u },\n        related = side?.related.orEmpty(),\n        isFav = false,\n        isSaved = false,\n        saveListId = "",\n    )\n}'),
            # 71k. ★ 外部播放改走系统选择器（扫描本机可用打开方式）+ 复制直链优先给在线原始 url
            ('                        DetailAction("📺 外部播放", busy) {\n                            try {\n                                com.han1me.HplayEnv.playExternal(HanimeClient.relayUrl(first.second))\n                                onToast("已交给系统播放器（${first.first}P，直连播放；不经网络策略）")\n                            } catch (t: Throwable) {\n                                onToast("打开外部播放器失败：${t.message}")\n                            }\n                        }\n                        DetailAction("🔗 复制直链", busy) {\n                            try {\n                                com.han1me.HplayEnv.copyText(first.second)\n                                onToast("已复制 ${first.first}P 直链（原始裸链）")\n                            } catch (t: Throwable) {\n                                onToast("复制失败：${t.message}")\n                            }\n                        }', '                        // 第 71 轮（用户报的两个 bug）：\n                        //  ① 「外部播放」要能**跳转外部播放器、扫描本机可用的打开方式**；\n                        //  ② 「复制直链」要给**原始在线直链**，不是本机 file:// 路径。\n                        //\n                        // 共同根因：本机条目的源清单第一项是 `file://…`（为了离线可播），\n                        // 而这两个按钮原来都直接用 `first.second`（第一项）。\n                        // 现在统一先挑「在线源」，本机路径只在没有在线源时才用。\n                        val onlineSrc = d.sources.firstOrNull { !it.second.startsWith("file://") }\n                        DetailAction("📺 外部播放", busy) {\n                            try {\n                                // 本机条目：把**文件**交给系统选择器（扫描本机可用的播放器让用户挑）；\n                                // 在线条目：交给系统的 ACTION_VIEW（浏览器/播放器都可能接）。\n                                val localPath = d.sources.firstOrNull()?.second\n                                val ok = if (localPath != null && localPath.startsWith("file://")) {\n                                    com.han1me.HplayEnv.playExternalFile(\n                                        java.net.URLDecoder.decode(localPath.removePrefix("file://"), "UTF-8"),\n                                    )\n                                } else {\n                                    com.han1me.HplayEnv.playExternal(HanimeClient.relayUrl(first.second))\n                                }\n                                if (ok) onToast("已打开系统选择器：选一个播放器即可")\n                            } catch (t: Throwable) {\n                                onToast("打开外部播放器失败：${t.message}")\n                            }\n                        }\n                        DetailAction("🔗 复制直链", busy) {\n                            try {\n                                // ★ 用户要的「之前的 url 直链」：优先复制**在线源**\n                                val toCopy = onlineSrc?.second ?: first.second\n                                com.han1me.HplayEnv.copyText(toCopy)\n                                onToast(\n                                    if (onlineSrc != null) "已复制原始直链（${onlineSrc.first}P，可在别处打开/下载）"\n                                    else "这个条目只留了本机文件路径（没有在线源可复制）"\n                                )\n                            } catch (t: Throwable) {\n                                onToast("复制失败：${t.message}")\n                            }\n                        }'),
            # 72a. ★ 用户页新增「退出登录」与「切换账户」按钮（走 onLogout 回调）
            ('            if (user == null) {\n                Button(\n                    onClick = onLogin,\n                    colors = ButtonDefaults.buttonColors(containerColor = AccentRed),\n                    shape = RoundedCornerShape(20.dp),\n                    modifier = Modifier.fillMaxWidth().height(40.dp),\n                ) { Text("登录 / 注册", fontSize = 13.sp) }\n                Spacer(Modifier.height(10.dp))\n            }', '            if (user == null) {\n                Button(\n                    onClick = onLogin,\n                    colors = ButtonDefaults.buttonColors(containerColor = AccentRed),\n                    shape = RoundedCornerShape(20.dp),\n                    modifier = Modifier.fillMaxWidth().height(40.dp),\n                ) { Text("登录 / 注册", fontSize = 13.sp) }\n                Spacer(Modifier.height(10.dp))\n            } else {\n                // 第 72 轮（用户要求）：**退出登录** + **切换账户**。\n                //\n                // 说明：官方源（hanime1.me）的登录态就是本机的 Cookie，所以两者都是\n                // 「清 Cookie + 让上层刷新」，差别只在切换账户会**顺带打开登录框**。\n                // 具体清 Cookie 与刷新由上层 [onLogout] 做 —— 本函数是纯展示组件，\n                // `user`/`profile` 都是入参（val），不能在这里改。\n                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                    OutlinedButton(\n                        onClick = { onLogout(false) },\n                        shape = RoundedCornerShape(18.dp),\n                        modifier = Modifier.weight(1f).height(36.dp),\n                    ) { Text("退出登录", fontSize = 12.sp, color = Color(0xFFE8E8EA)) }\n                    OutlinedButton(\n                        onClick = { onLogout(true) },\n                        shape = RoundedCornerShape(18.dp),\n                        modifier = Modifier.weight(1f).height(36.dp),\n                    ) { Text("切换账户", fontSize = 12.sp, color = Color(0xFFE8E8EA)) }\n                }\n                Spacer(Modifier.height(10.dp))\n            }'),
            # 72b. UserTab 新增 onLogout 形参（本组件是纯展示，不能改入参）
