            ('// ---------- 列表页（搜索 / 分区 / 我的清单） ----------\n\n@Composable\nprivate fun ListContent(', '// ---------- 新番预告页（/previews/yyyyMM） ----------\n\n/**\n * 「新番预告」内容页（第 74 轮）。\n *\n * 为什么单独一页：站方把新番预告放在独立地址 `previews/YYYYMM`，\n * 而且**版式与首页/搜索页完全不同**（没有 video-item-container），\n * 复用 [ListContent] 只会得到空列表。\n *\n * 界面组成（对齐参考实现 Han1meViewer 的 PreviewScreen）：\n *  · 顶部：`← 返回` + 月份标签 + `‹ 上一月` / `下一月 ›`；\n *  · 列表：每条一张卡（封面 + 原标题 + 译名 + 厂商/发售日 + 标签 + 简介）；\n *  · 取不到时**如实显示原因**（站方 500 与解析为空分开说）。\n */\n@OptIn(ExperimentalLayoutApi::class)\n@Composable\nprivate fun PreviewContent(\n    monthCode: String,\n    page: X99.PreviewPage?,\n    loading: Boolean,\n    onBack: () -> Unit,\n    onPrevMonth: () -> Unit,\n    onNextMonth: () -> Unit,\n    onRetry: () -> Unit,\n    onOpenVideoCode: (String) -> Unit,\n) {\n    Column(\n        Modifier.fillMaxSize().verticalScroll(rememberScrollState())\n            .padding(horizontal = 16.dp, vertical = 12.dp),\n    ) {\n        // 顶栏：返回 + 月份 + 翻月\n        Row(verticalAlignment = Alignment.CenterVertically) {\n            Text(\n                "← 返回", color = AccentRed, fontSize = 14.sp,\n                modifier = Modifier.clickable { onBack() }.padding(vertical = 4.dp),\n            )\n            Spacer(Modifier.width(12.dp))\n            Text("新番预告", color = Color.White, fontSize = 17.sp, fontWeight = FontWeight.Bold)\n            Spacer(Modifier.width(8.dp))\n            Text(X99.monthLabel(monthCode), color = TextDim, fontSize = 13.sp)\n            Spacer(Modifier.weight(1f))\n            Text(\n                "‹ 上一月", color = Color(0xFFE8E8EA), fontSize = 12.sp,\n                modifier = Modifier.clip(RoundedCornerShape(12.dp)).background(CardColorSoft)\n                    .clickable { onPrevMonth() }.padding(horizontal = 10.dp, vertical = 5.dp),\n            )\n            Spacer(Modifier.width(6.dp))\n            Text(\n                "下一月 ›", color = Color(0xFFE8E8EA), fontSize = 12.sp,\n                modifier = Modifier.clip(RoundedCornerShape(12.dp)).background(CardColorSoft)\n                    .clickable { onNextMonth() }.padding(horizontal = 10.dp, vertical = 5.dp),\n            )\n        }\n        Spacer(Modifier.height(10.dp))\n        when {\n            loading -> {\n                Box(Modifier.fillMaxWidth().height(120.dp), contentAlignment = Alignment.Center) {\n                    CircularProgressIndicator(color = AccentRed)\n                }\n            }\n            page == null || page.items.isEmpty() -> {\n                // **如实说原因**：站方 500 与「这月没有预告」不是一回事\n                Column(Modifier.fillMaxWidth().padding(vertical = 24.dp)) {\n                    Text(\n                        page?.error?.ifBlank { null } ?: "这一月没有取到预告",\n                        color = TextDim, fontSize = 12.5.sp, lineHeight = 19.sp,\n                    )\n                    Spacer(Modifier.height(10.dp))\n                    Text(\n                        "重试", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.SemiBold,\n                        modifier = Modifier.clip(RoundedCornerShape(14.dp)).background(AccentRed)\n                            .clickable { onRetry() }.padding(horizontal = 14.dp, vertical = 7.dp),\n                    )\n                }\n            }\n            else -> {\n                page.items.forEach { it0 ->\n                    Column(\n                        Modifier.fillMaxWidth().padding(vertical = 6.dp)\n                            .clip(RoundedCornerShape(10.dp)).background(CardColor).padding(10.dp),\n                    ) {\n                        Row(verticalAlignment = Alignment.Top) {\n                            Box(\n                                Modifier.width(96.dp).height(134.dp).clip(RoundedCornerShape(8.dp))\n                                    .background(Color(0xFF1C1C20)),\n                                contentAlignment = Alignment.Center,\n                            ) {\n                                if (it0.cover.isNotBlank()) {\n                                    com.han1me.web.HplayThumb(it0.cover, it0.title, Modifier.fillMaxSize())\n                                } else {\n                                    Text("🎬", color = Color(0xFF4A4A52), fontSize = 22.sp)\n                                }\n                            }\n                            Spacer(Modifier.width(10.dp))\n                            Column(Modifier.weight(1f)) {\n                                Text(\n                                    it0.videoTitle.ifBlank { it0.title },\n                                    color = Color.White, fontSize = 13.sp, fontWeight = FontWeight.SemiBold,\n                                    maxLines = 3, overflow = TextOverflow.Ellipsis,\n                                )\n                                if (it0.title.isNotBlank() && it0.title != it0.videoTitle) {\n                                    Spacer(Modifier.height(3.dp))\n                                    Text(\n                                        it0.title, color = TextFaint, fontSize = 10.5.sp,\n                                        maxLines = 2, overflow = TextOverflow.Ellipsis,\n                                    )\n                                }\n                                Spacer(Modifier.height(4.dp))\n                                if (it0.brand.isNotBlank() || it0.releaseDate.isNotBlank()) {\n                                    Text(\n                                        listOf(it0.brand, it0.releaseDate).filter { it.isNotBlank() }\n                                            .joinToString("\u3000·\u3000"),\n                                        color = TextDim, fontSize = 10.5.sp,\n                                    )\n                                }\n                                if (it0.tags.isNotEmpty()) {\n                                    Spacer(Modifier.height(5.dp))\n                                    FlowRow(\n                                        horizontalArrangement = Arrangement.spacedBy(5.dp),\n                                        verticalArrangement = Arrangement.spacedBy(5.dp),\n                                    ) {\n                                        it0.tags.take(6).forEach { tg ->\n                                            Text(\n                                                tg, color = TextDim, fontSize = 9.5.sp,\n                                                modifier = Modifier.clip(RoundedCornerShape(9.dp))\n                                                    .background(CardColorSoft)\n                                                    .padding(horizontal = 7.dp, vertical = 2.dp),\n                                            )\n                                        }\n                                    }\n                                }\n                                if (it0.videoCode.isNotBlank()) {\n                                    Spacer(Modifier.height(7.dp))\n                                    Text(\n                                        "查看正片 ›", color = AccentRed, fontSize = 11.5.sp,\n                                        modifier = Modifier.clickable { onOpenVideoCode(it0.videoCode) },\n                                    )\n                                }\n                            }\n                        }\n                        if (it0.introduction.isNotBlank()) {\n                            Spacer(Modifier.height(7.dp))\n                            Text(\n                                it0.introduction, color = TextDim, fontSize = 11.sp, lineHeight = 16.sp,\n                                maxLines = 6, overflow = TextOverflow.Ellipsis,\n                            )\n                        }\n                    }\n                }\n                Spacer(Modifier.height(18.dp))\n            }\n        }\n    }\n}\n\n// ---------- 列表页（搜索 / 分区 / 我的清单） ----------\n\n@Composable\nprivate fun ListContent('),
