            ('    /** 复制「我的主页链接」——站点自己在个人页上就有这个按钮（`id="copy-text"` + copyToClipboard）。 */\n    fun copyProfileHome() {\n        val p = profile\n        if (p == null) { toast = "未登录：没有个人主页链接可复制"; return }\n        clipboard.setText(androidx.compose.ui.text.AnnotatedString(p.home))\n        toast = "已复制个人主页链接 ${p.home}"\n    }', '    /**\n     * 复制「我的主页链接」——站点自己在个人页上就有这个按钮（`id="copy-text"` + copyToClipboard）。\n     *\n     * ★ 第 80 轮修（用户报「主页链接时有时无，之前有一次 id 和用户名显示了」）：\n     *\n     * 根因：这里**只认 `profile`**，而 `profile` 是异步拉取的（`/user/<uid>`）。\n     * 它没回来 / 那一次请求失败时，`profile == null` → 直接报「未登录」，\n     * 可用户明明是登录状态（界面上邮箱都在）。表现就是「时有时无」。\n     *\n     * 修法：**分层兜底**，只要能确定 uid 就一定能给出主页链接：\n     *  ① profile.home（最准，站点自己给的）\n     *  ② 用 HanimeClient.userId() 拼 `${BASE}/user/<uid>`\n     *  ③ 都没有才如实说「未登录 / 还没拿到账号信息」\n     */\n    fun copyProfileHome() {\n        val home = profile?.home?.takeIf { it.isNotBlank() }\n            ?: runCatching {\n                val uid = HanimeClient.userId()\n                if (uid.isNullOrBlank()) null else "${HanimeClient.BASE}/user/$uid"\n            }.getOrNull()\n        if (home.isNullOrBlank()) {\n            toast = if (user != null) "还没拿到账号信息，稍后重试（或下拉刷新）" else "未登录：没有个人主页链接可复制"\n            return\n        }\n        clipboard.setText(androidx.compose.ui.text.AnnotatedString(home))\n        toast = "已复制个人主页链接 $home"\n    }'),
