            ('        if (mirror) {\n            // 优选线路：媒体链路只放行真实浏览器（内置播放器会被 CDN 403）→ 点击视频直接跳转播放\n            webPage = WebPage(v.url, v.title, play = true)\n            return\n        }', '        if (mirror) {\n            // ★★ 第 81 轮修（用户报的真问题）：「han1me 的优选路线还是网页而且播放时还被广告跳转，\n            //   全部做成原生板块同步官方源 ui 复刻，介绍页什么的全部都要适配原生」。\n            //\n            // 原来这里**无条件跳 WebView**（注释说「媒体链路只放行真实浏览器」）——\n            // 于是优选线路完全没有原生体验：没有原生介绍页、播放时还会被网页广告跳转。\n            //\n            // 修法：**先走原生详情页**（X99.metaDetail 能抓任意站点的 og:title/og:image/\n            //   og:description/标签，与官方源同一套原生界面），拿不到详情才回落到 WebView。\n            //   这样：列表 → 原生介绍页 → 原生播放（有原生清单就用，没有则给「网页播放」按钮）。\n            detailLoading = true\n            detail = null\n            detailFromBoard = true\n            scope.launch(Dispatchers.IO) {\n                val d = runCatching { X99.metaDetail(v) }.getOrNull()\n                kotlinx.coroutines.withContext(Dispatchers.Main) {\n                    detailLoading = false\n                    if (d != null) {\n                        X99.adoptDetail(d)\n                        detail = d\n                    } else {\n                        // 连介绍页都拿不到（站点改版 / 被频控）才回落网页版 ——\n                        // 卡在空白页比退回网页版更糟。\n                        webPage = WebPage(v.url, v.title, play = true)\n                    }\n                }\n            }\n            return\n        }'),
