            ('    val local = remember(favTick) { X99.favs() }\n    val boards = remember(favTick, favFilter) { listOf("全部") + X99.favBoards() }\n    val shown = if (favFilter == "全部") local else local.filter { it.board == favFilter }', '    val local = remember(favTick) { X99.favs() }\n    val boards = remember(favTick, favFilter) { listOf("全部") + X99.favBoards() }\n    val shown = if (favFilter == "全部") local else local.filter { it.board == favFilter }\n    // ★★ 第 90 轮（用户要求）：「收藏页的本地收藏板块也做一个翻页按钮，\n    //   具体都和已下载视频页的一样就行」。\n    //\n    // 与已下载页同一口径：本地收藏整表分页（每页 12 条），\n    // 翻页控件放在「本站收藏 · N 条」那一行的右侧（与已下载页的「已下载 N」右边一致）。\n    val favPageSize = 12\n    val favPageCount = ((shown.size + favPageSize - 1) / favPageSize).coerceAtLeast(1)\n    var favPage by remember(favFilter, favTick) { mutableStateOf(0) }\n    // 筛选或收藏数变化后页码可能越界，收敛回合法范围。\n    if (favPage > favPageCount - 1) favPage = favPageCount - 1\n    val shownPage = shown.drop(favPage * favPageSize).take(favPageSize)'),
            # 90c. ★★ 收藏页标题行加翻页控件
            ('        Text("本站收藏 · ${local.size} 条", color = Color(0xFFE8E8EA), fontSize = 13.sp, fontWeight = FontWeight.SemiBold)', '        // 标题行：左侧「本站收藏 · N 条」，右侧翻页控件（与已下载页同一位置口径）。\n        Row(verticalAlignment = Alignment.CenterVertically) {\n            Text("本站收藏 · ${local.size} 条", color = Color(0xFFE8E8EA), fontSize = 13.sp, fontWeight = FontWeight.SemiBold)\n            if (favPageCount > 1) {\n                Spacer(Modifier.weight(1f))\n                com.han1me.ui.PageStepper(\n                    page = favPage,\n                    pageCount = favPageCount,\n                    onPrev = { if (favPage > 0) favPage-- },\n                    onNext = { if (favPage < favPageCount - 1) favPage++ },\n                )\n            }\n        }'),
