            # 93a. ★★ id/统计分层兜底（profile 抓失败也显示 @uid，不再整块消失）
            ('            if (profile != null) {\n                Text(\n                    "@ ${profile.uid}" + if (profile.stats.isNotBlank()) "\u3000${profile.stats}" else "",\n                    color = TextFaint, fontSize = 11.5.sp, modifier = Modifier.offset(y = (-8).dp),\n                )\n            } else if (mirror) {\n                Text("当前站源：优选线路（账号功能不可用）", color = TextFaint, fontSize = 11.5.sp)\n            }', '            // ★★ 第 93 轮修（用户报「红色标注的 id / 订阅者数 / 影片数时而显示时而不显示」）：\n            //\n            // 根因：这一整行原来写在 `if (profile != null)` 里，而 profile 来自\n            // `/user/<uid>` 的**一次异步抓取** —— 抓失败/超时就整块消失。\n            // 用户看到的就是「一会儿有一会儿没有」。\n            //\n            // 修法：**分层兜底**，让 id 默认一定显示：\n            //   ① profile 有 → 显示 @uid + 订阅/影片统计；\n            //   ② profile 没有但有 uid（HanimeClient.userId() 能拿到）→ 至少显示 @uid；\n            //   ③ 都没有且是优选线路 → 如实说明账号功能不可用。\n            val uidFallback = remember(user, profile) {\n                if (profile != null) "" else runCatching { HanimeClient.userId() }.getOrNull().orEmpty()\n            }\n            if (profile != null) {\n                Text(\n                    "@ ${profile.uid}" + if (profile.stats.isNotBlank()) "\u3000${profile.stats}" else "",\n                    color = TextFaint, fontSize = 11.5.sp, modifier = Modifier.offset(y = (-8).dp),\n                )\n            } else if (uidFallback.isNotBlank()) {\n                // 统计还没拿到（或那次抓取失败）—— 先把 id 显示出来，不让整块消失。\n                Text(\n                    "@ $uidFallback\u3000统计加载中…",\n                    color = TextFaint, fontSize = 11.5.sp, modifier = Modifier.offset(y = (-8).dp),\n                )\n            } else if (mirror) {\n                Text("当前站源：优选线路（账号功能不可用）", color = TextFaint, fontSize = 11.5.sp)\n            }'),
            # 94a. ★★ 每次进用户页补抓 profile（修「统计时而有时而没有」）
