            ('@OptIn(ExperimentalLayoutApi::class)\n@Composable\nfun X99Dialog(', '/**\n * **本命板块（hanime1.me）专用的小线路弹窗**（第 75 轮，用户要求）。\n *\n * 用户原话：「你单独给 han1me 做一个优选弹窗，别把其他板块放进来，就是小弹出式提示框就行，不用那么大」。\n *\n * 与 [X99Dialog] 的区别（**各管一摊，互不掺和**）：\n *  · 这个**只有 hanime1 的线路**：第 1 条＝官方源（默认选中），其余为镜像；\n *  · **不列任何其它板块**（xchina / 36co / qinav… 一个都不出现）；\n *  · **尺寸小得多**：宽度 78%、高度上限 420dp，居中弹出，不铺满屏。\n *\n * 为什么单开一个而不是给 X99Dialog 加参数：\n *  X99Dialog 的职责是「站点合集：切板块 + 选线路」，它的站点表、切换按钮、说明文字\n *  都是围绕「多板块」组织的。硬塞一个「只显示 hanime」模式会让两边的条件分支互相牵制，\n *  以后改一个动另一个。**分开写、各自简单**更稳。\n *\n * @param currentLineUrl 当前线路（空串 = 官方源），用于打勾\n * @param lines 本命板块的线路（含官方源），由调用方用 X99.hanimeSite() 取\n */\n@OptIn(ExperimentalLayoutApi::class)\n@Composable\nfun HanimeLineDialog(\n    currentLineUrl: String,\n    lines: List<X99Line>,\n    onClose: () -> Unit,\n    onPick: (X99Line) -> Unit,\n    onToast: (String) -> Unit,\n) {\n    val scope = rememberCoroutineScope()\n    val delay = remember { mutableStateMapOf<String, Long>() }\n    var round by remember { mutableStateOf(0) }\n    val official = X99Line(X99.OFFICIAL_HANIME, X99.OFFICIAL_HANIME + "/")\n    // 第 1 条永远官方源；其余镜像去重、剔掉官方源\n    val shown = remember(lines, round) {\n        listOf(official) + lines.filterNot { it.url == X99.OFFICIAL_HANIME }.distinctBy { it.url }\n    }\n    // 打开即测速（round 变化＝重新测速）\n    LaunchedEffect(round, shown) {\n        shown.forEach { ln ->\n            if (delay[ln.url] == null || round > 0) {\n                delay[ln.url] = -2L\n                scope.launch {\n                    val ms = withContext(Dispatchers.IO) { X99.testLine(ln) }\n                    delay[ln.url] = ms\n                }\n            }\n        }\n    }\n    val picked = currentLineUrl.ifBlank { X99.OFFICIAL_HANIME }\n    Box(Modifier.fillMaxSize().background(Color(0x99000000)).clickable { onClose() }) {\n        Column(\n            Modifier\n                .align(Alignment.Center)\n                .padding(bottom = 74.dp)\n                // **小**：宽度 78%，高度上限 420dp（不铺满屏）\n                .fillMaxWidth(0.78f)\n                .heightIn(max = 420.dp)\n                .clip(RoundedCornerShape(14.dp))\n                .background(Color(0xFF141417))\n                .clickable(enabled = false) {}\n                .verticalScroll(rememberScrollState())\n                .padding(14.dp),\n        ) {\n            Row(verticalAlignment = Alignment.CenterVertically) {\n                Text("hanime1.me 线路", color = Color.White, fontSize = 15.sp, fontWeight = FontWeight.Bold)\n                Spacer(Modifier.weight(1f))\n                TextButton(onClick = { round += 1 }) { Text("重新测速", color = AccentRed, fontSize = 11.sp) }\n                TextButton(onClick = onClose) { Text("关闭", fontSize = 11.sp) }\n            }\n            Text("官方源可登录、DoH/代理生效；镜像为直连。", color = TextFaint, fontSize = 10.sp)\n            Spacer(Modifier.height(8.dp))\n            shown.forEach { ln ->\n                val d = delay[ln.url]\n                val isOfficial = ln.url == X99.OFFICIAL_HANIME\n                val selected = ln.url == picked\n                Row(\n                    verticalAlignment = Alignment.CenterVertically,\n                    modifier = Modifier.fillMaxWidth().padding(vertical = 3.dp)\n                        .clip(RoundedCornerShape(10.dp))\n                        .background(if (selected) Color(0xFF23232A) else Color(0xFF1A1A1E))\n                        .clickable { onPick(ln) }\n                        .padding(horizontal = 10.dp, vertical = 8.dp),\n                ) {\n                    Text(if (selected) "✔" else "○", color = if (selected) AccentRed else TextFaint, fontSize = 12.sp)\n                    Spacer(Modifier.width(8.dp))\n                    Text(\n                        if (isOfficial) "官方源 hanime1.me" else ln.host,\n                        color = if (selected) Color.White else Color(0xFFCFCFD4), fontSize = 12.sp,\n                        maxLines = 1, overflow = TextOverflow.Ellipsis, modifier = Modifier.weight(1f),\n                    )\n                    Text(\n                        when {\n                            d == null -> "…"\n                            d == -2L -> "测速中"\n                            d < 0 -> if (isOfficial) "官方源" else "线路异常"\n                            else -> "$d ms"\n                        },\n                        color = when {\n                            d == null || d == -2L -> TextFaint\n                            d < 0 -> if (isOfficial) TextFaint else Color(0xFFFF8A8A)\n                            else -> Color(0xFF7ED97E)\n                        },\n                        fontSize = 11.sp,\n                    )\n                }\n            }\n        }\n    }\n}\n\n@OptIn(ExperimentalLayoutApi::class)\n@Composable\nfun X99Dialog('),
